// v512: アプリ本体（index.htmlから分離。ブラウザがコンパイル結果を保存でき、2回目以降の起動が速くなる）
var APP_JS_VERSION = 'v680';
// index.htmlとapp.jsの版ズレ検知：アップロード途中や古いキャッシュで組み合わせが食い違ったら
// app.jsのキャッシュを捨てて1回だけ読み直す。それでも合わなければ案内を出して起動を止める（壊れた組み合わせで保存させない）
(function() {
  var want = window.GM_EXPECT_JS;
  if (!want || want === APP_JS_VERSION) { try { sessionStorage.removeItem('gm_jsMismatch'); } catch(e0) {} return; }
  var tries = 0;
  try { tries = parseInt(sessionStorage.getItem('gm_jsMismatch') || '0', 10) || 0; sessionStorage.setItem('gm_jsMismatch', String(tries + 1)); } catch(e1) {}
  var purge = (window.caches && caches.keys) ? caches.keys().then(function(keys) {
    return Promise.all(keys.map(function(k) { return caches.open(k).then(function(c) { return c.keys().then(function(reqs) {
      return Promise.all(reqs.filter(function(r) { return /app\.js/.test(r.url) || /index\.html$|\/$/.test(r.url); }).map(function(r) { return c.delete(r); }));
    }); }); }));
  }) : Promise.resolve();
  if (tries < 2) {
    purge.then(function() { location.reload(); }, function() { location.reload(); });
  } else {
    var msg = document.createElement('div');
    msg.style.cssText = 'position:fixed;inset:0;z-index:99999;background:#0b0e14;color:#e5e7eb;display:flex;align-items:center;justify-content:center;padding:24px;text-align:center;font-size:15px;line-height:1.9;font-family:sans-serif';
    msg.innerHTML = 'アプリを更新中です。<br>1〜2分ほど待ってから開き直してください。<br><span style="font-size:12px;opacity:.6">(' + want + ' / ' + APP_JS_VERSION + ')</span>';
    (document.body || document.documentElement).appendChild(msg);
  }
  throw new Error('GROOVE: index.html(' + want + ') と app.js(' + APP_JS_VERSION + ') の版が一致しません');
})();
