// Firestore保存
// v387: オフライン編集対応 — オフライン中の書き込みは端末に記録され、復帰時にFirestoreが自動送信する。
//        その間Promiseは解決しないため、オフライン時は即時resolveしてUI（トースト・画面遷移）を止めない。
function fsSet(path, data) {
  if (!db) return Promise.resolve();
  var p = db.doc(path).set(data, { merge: true });
  if (!navigator.onLine) {
    p.catch(function(){});
    _offlineDirtyNote();
    return Promise.resolve();
  }
  return p;
}
// v387: オフライン保存の案内（連打されないよう10秒に1回）
var _offlineNoteAt = 0;
function _offlineDirtyNote() {
  window._offlineDirty = true;
  var now = Date.now();
  if (now - _offlineNoteAt < 10000) return;
  _offlineNoteAt = now;
  try { toast('オフラインで保存しました（オンライン復帰時に自動同期）'); } catch(e) {}
}
// v387: オフラインバナー — 下部タブの上に表示。復帰時は同期中トースト。
function _netBannerUpdate() {
  var b = document.getElementById('netBanner');
  if (!navigator.onLine) {
    if (!b) {
      b = document.createElement('div');
      b.id = 'netBanner';
      b.textContent = '📡 オフライン閲覧中 — 最後に同期した内容を表示しています（編集は復帰時に自動同期）';
      document.body.appendChild(b);
    }
  } else if (b && b.parentNode) {
    b.parentNode.removeChild(b);
    if (window._offlineDirty) {
      window._offlineDirty = false;
      try { toast('📡 オンラインに復帰しました — 変更を同期中'); } catch(e2) {}
    }
  }
}
window.addEventListener('online', _netBannerUpdate);
window.addEventListener('offline', _netBannerUpdate);
setTimeout(function(){ try { _netBannerUpdate(); } catch(e) {} }, 0);

// v511: 起動時の先読み。プロフィール取得を待たずに主要データの取得を並列で開始し、
// 同じパスの最初のfsGet/fsGetColがその結果を受け取る（読み取り回数は増えない）
var _fsPrefetch = {};
function _fsTakePrefetch(key) {
  var e = _fsPrefetch[key];
  if (!e) return null;
  delete _fsPrefetch[key];
  return (Date.now() - e.at < 30000) ? e.p : null;
}
function fsPrefetch(path, isCol) {
  if (!db || _fsPrefetch[(isCol ? 'c:' : 'd:') + path]) return;
  var pr = isCol ? _fsGetColRaw(path) : _fsGetRaw(path);
  pr.catch(function(){});
  _fsPrefetch[(isCol ? 'c:' : 'd:') + path] = { p: pr, at: Date.now() };
}
function _startupPrefetch(uid) {
  try {
    var mo = state.currentMonth;
    if (!uid || !mo) return;
    fsPrefetch('maps/' + uid + '/months/' + mo + '_current');
    fsPrefetch('maps/' + uid + '/months/' + mo + '_ideal');
    fsPrefetch('maps/' + uid + '/stats/' + mo);
    fsPrefetch('maps/' + uid + '/events', true);
    fsPrefetch('maps/' + uid + '/meta/eventCategories');
    fsPrefetch('maps/' + uid + '/meta/goals');
  } catch(e) {}
}
function _fsGetRaw(path) {
  return db.doc(path).get().then(function(doc) {
    return doc.exists ? doc.data() : null;
  });
}
// Firestore読み込み
function fsGet(path) {
  if (!db) return Promise.resolve(null);
  return _fsTakePrefetch('d:' + path) || _fsGetRaw(path);
}

// コレクション読み込み
function fsGetCol(path) {
  if (!db) return Promise.resolve([]);
  return _fsTakePrefetch('c:' + path) || _fsGetColRaw(path);
}
function _fsGetColRaw(path) {
  return db.collection(path).get().then(function(snap) {
    var docs = [];
    snap.forEach(function(d) { docs.push(Object.assign({id: d.id}, d.data())); });
    return docs;
  });
}

