    state.freshData = JSON.parse(JSON.stringify(state.freshData || {}));

    // 保存（翌月への全置換コピー：マージで旧データを復活させない）
    window._skipMergeOnce = true;
    buildMonthSelector();
    autoSave();
    renderCurrentView();
    var up = changes.filter(function(c){ return c.kind === 'promote'; }).length;
    var dn = changes.filter(function(c){ return c.kind === 'demote'; }).length;
    var extra = (up || dn) ? '（🎉' + up + ' / ⚠️' + dn + '）' : '';
    toast(nextMonth + ' にコピーしました ✓ ' + extra);
