// ── 右クリックコンテキストメニュー ──
var _ctxTargetId = null;

// documentレベルでcontextmenuを捕捉（Safari対応）
document.addEventListener('contextmenu', function(e) {
  var target = e.target;
  var memberId = null;

  // SVGノード（oval-node g要素）を検索 - Chrome対応で自分自身もチェック
  var node = target;
  while (node && node !== document) {
    if (node.getAttribute && node.getAttribute('data-mid')) {
      memberId = node.getAttribute('data-mid');
      break;
    }
    if (node.getAttribute && node.getAttribute('data-cid')) {
      memberId = node.getAttribute('data-cid');
      break;
    }
    node = node.parentNode;
  }

  if (memberId) {
    e.preventDefault();
    openCtxMenu(memberId, e.clientX, e.clientY);
  }
});

function openCtxMenu(memberId, x, y) {
  if (/^MG_/.test(memberId)) { mgNodeClick(memberId); return; } // 結合ノード→編集権限があれば相手MAPへ
  _ctxTargetId = memberId;
  var menu = document.getElementById('ctxMenu');
  var label = document.getElementById('ctxLabel');
  if (!menu) return;

  // メンバー名を表示
  var m = null;
  var members = state.members.concat(state.idealMembers || []);
  for (var i=0; i<members.length; i++) {
    if (members[i].id === memberId) { m = members[i]; break; }
  }
  if (label && m) label.textContent = (m.lastName||'') + ' ' + (m.firstName||'');

  // v497: メニューの実寸を測って画面内にクランプ（端のメンバーで見切れない）
  menu.style.left = x + 'px';
  menu.style.top  = y + 'px';
  menu.classList.add('open');
  var _mw7 = menu.offsetWidth || 200, _mh7 = menu.offsetHeight || 220;
  menu.style.left = Math.max(8, Math.min(x, window.innerWidth - _mw7 - 8)) + 'px';
  menu.style.top  = Math.max(8, Math.min(y, window.innerHeight - _mh7 - 8)) + 'px';

  // インスタ・LINEボタンの表示切替
  var instaBtn = document.getElementById('ctxInsta');
  if (instaBtn) {
    instaBtn.style.display = (m && m.instaUrl) ? '' : 'none';
  }
  var lineBtn = document.getElementById('ctxLine');
  if (lineBtn) {
    lineBtn.style.display = (m && m.lineId) ? '' : 'none';
  }

  // メニュー外クリックで閉じる（contextmenuは除外）
  setTimeout(function() {
    document.addEventListener('click', closeCtxMenu, { once: true });
  }, 50);
}

function closeCtxMenu() {
  var menu = document.getElementById('ctxMenu');
  if (menu) menu.classList.remove('open');
  _ctxTargetId = null;
}

function ctxAddChild() {
  var tid = _ctxTargetId; // closeの前に保存
  closeCtxMenu();
  if (currentView === 'ideal' && tid && state.isEditor && typeof idqOpen === 'function') { idqOpen(tid); return; } // v558: 理想MAPはかんたん編集の「直下に追加」へ
  selectedParentId = tid;
  openQuickAdd(); // v487
}

function ctxEdit() {
  var tid = _ctxTargetId;
  closeCtxMenu();
  if (currentView === 'ideal' && tid && state.isEditor && typeof idqOpen === 'function') { idqOpen(tid); return; } // v558: 理想MAPはかんたん編集
  if (tid && state.isEditor) openEdit(tid);
}

function ctxOpenInsta() {
  closeCtxMenu();
  var members = state.members.concat(state.idealMembers || []);
  for (var i=0; i<members.length; i++) {
    if (members[i].id === _ctxTargetId && members[i].instaUrl) {
      window.open(members[i].instaUrl, '_blank');
      return;
    }
  }
}
// ── LINE：ID または URL から LINE を開く ──
function _lineUrl(v) {
  v = (v || '').trim();
  if (!v) return '';
  if (/^https?:\/\//i.test(v)) return v;            // フルURLはそのまま
  if (/^line:\/\//i.test(v)) return v;              // アプリスキーム
  var id = v.replace(/^~/, '').replace(/^@/, '');   // 先頭の ~ や @ は除去
  return 'https://line.me/R/ti/p/~' + encodeURIComponent(id);
}
function openLineChat(v) {
  var u = _lineUrl(v);
  if (u) window.open(u, '_blank');
  else if (typeof toast === 'function') toast('LINE ID / URL が未設定です');
}
function openLineChatFromEdit() {
  var el = document.getElementById('fLine');
  openLineChat(el ? el.value : '');
}
function openLineChatById(mid) {
  var members = state.members.concat(state.idealMembers || []);
  for (var i=0; i<members.length; i++) {
    if (members[i].id === mid) { openLineChat(members[i].lineId); return; }
  }
}
function ctxOpenLine() {
  var tid = _ctxTargetId;
  closeCtxMenu();
  openLineChatById(tid);
}

function ctxDelete() {
  var tid = _ctxTargetId;
  closeCtxMenu();
  if (!tid || !state.isEditor) return;
  // v558: 理想MAPでは理想MAPから削除（これまでは現状MAPの同じ人を消していた／理想で追加した新規は何も起きなかった）
  if (currentView === 'ideal') { _idealRemove(tid); return; }
  _ctxTargetId = tid; // 一時的に復元
  var m = null;
  for (var i=0; i<state.members.length; i++) {
    if (state.members[i].id === tid) { m = state.members[i]; break; }
  }
  if (!m) return;
  var name = (m.lastName||'') + (m.firstName||'');
  if (!confirm(name + ' を削除しますか？')) return;
  var delParent = '';
  for (var di=0; di<state.members.length; di++) {
    if (state.members[di].id === tid) {
      state.members[di].deleted = true;
      delParent = state.members[di].parentId || '';
      break;
    }
  }
  // 子を親に付け替え
  for (var ci=0; ci<state.members.length; ci++) {
    if (state.members[ci].parentId === tid) {
      state.members[ci].parentId = delParent;
    }
  }
  renderCurrentView();
  autoSave();
}


// ── 段数フィルター ──
var depthFilter = null; // null=全表示, 数値=その段数まで

// ── レベル（段数）展開：選択した段まで一気に開く ──
function buildLevelSelector(members) {
  var sel = document.getElementById('levelSelect');
  var wrap = document.getElementById('depthFilterWrap');
  if (!sel || !wrap) return;
  var maxD = 0;
  members.forEach(function(m){ var d = calcMemberDepth(m, members); if (d > maxD) maxD = d; });
  if (maxD < 1) { wrap.style.display = 'none'; return; }
  wrap.style.display = 'flex';
  var cur = sel.value || '2';
  var opts = '';
  for (var n = 1; n <= maxD; n++) opts += '<option value="' + n + '">' + n + '段まで</option>';
  opts += '<option value="all">全部表示</option>';
  sel.innerHTML = opts;
  // 現在値を維持（範囲内なら）
  if (cur === 'all' || (parseInt(cur, 10) >= 1 && parseInt(cur, 10) <= maxD)) sel.value = cur;
  else sel.value = String(Math.min(2, maxD));
}
function expandToLevel(n) {
  var mapType = (currentView === 'ideal') ? 'ideal' : 'current';
  // 結合(MG_)ノードも含めた合成後リストで開閉フラグを立てる（全段表示が結合ツリーにも効くように）
  var members = composeMergedInto(membersForMap(mapType), mapType);
  // 大組織の全展開は以後の再描画がすべて重くなるため確認（レベル選択でいつでも畳み直せる）
  if (n === 'all' && members.length > 300 && !confirm(members.length + '人すべて展開すると動作が重くなる場合があります。展開しますか？\n（レベル選択でいつでも畳み直せます）')) {
    if (typeof buildLevelSelector === 'function') buildLevelSelector(members); // セレクタ表示を元に戻す
    return;
  }
  if (!window._treeOpen) window._treeOpen = {};
  members.forEach(function(m){
    var d = calcMemberDepth(m, members);
    window._treeOpen[m.id] = (n === 'all') ? true : (d < parseInt(n, 10));
  });
  renderTree(mapType);
}
function buildDepthFilter(members) {
  var wrap = document.getElementById('depthFilterBtns');
  if (!wrap) return;

  // 最大段数を計算
  var maxDepth = 0;
  members.forEach(function(m) {
    var d = calcMemberDepth(m, members);
    if (d > maxDepth) maxDepth = d;
  });

  wrap.innerHTML = '';

  // 「全て」ボタン
  var allBtn = document.createElement('div');
  allBtn.textContent = '全て';
  var allActive = depthFilter === null;
  allBtn.style.cssText = 'font-size:11px;padding:3px 10px;border-radius:10px;cursor:pointer;font-family:Inter,IBM Plex Mono,monospace;border:1px solid var(--accent);background:' + (allActive ? 'var(--accent)' : 'transparent') + ';color:' + (allActive ? '#000' : 'var(--accent)');
  allBtn.onclick = function() { depthFilter = null; renderCurrentView(); };
  wrap.appendChild(allBtn);

  // 各段数ボタン
  for (var d = 0; d <= maxDepth; d++) {
    (function(depth) {
      var btn = document.createElement('div');
      btn.textContent = depth + '段';
      var isActive = depthFilter === depth;
      btn.style.cssText = 'font-size:11px;padding:3px 10px;border-radius:10px;cursor:pointer;font-family:Inter,IBM Plex Mono,monospace;border:1px solid ' + (isActive ? 'var(--accent)' : 'var(--border)') + ';background:' + (isActive ? 'var(--accent)' : 'transparent') + ';color:' + (isActive ? '#000' : 'var(--text-dim)');
      btn.onclick = function() { depthFilter = depth; renderCurrentView(); };
      wrap.appendChild(btn);
    })(d);
  }
}

function applyDepthFilter(members) {
  if (depthFilter === null) return members;
  return members.filter(function(m) {
    return calcMemberDepth(m, members) <= depthFilter;
  });
}

// ── 地域フィルタ（配列は崩さず、非該当を薄く表示）──
var regionFilter = '';
function buildRegionFilter(members, wrap) {
  if (!wrap) wrap = document.getElementById('depthFilterBtns');
  if (!wrap) return false;
  var seen = {}, regions = [];
  members.forEach(function(m){ var r=normalizeRegionValue(m.region); if(r && !seen[r]){ seen[r]=1; regions.push(r); } }); // v496: 表記ゆれを正規化してチップ生成
  if (!regions.length) { regionFilter = ''; return false; }
  regions.sort();
  var lbl = document.createElement('span'); lbl.textContent = '地域'; lbl.style.cssText = 'font-size:11px;color:var(--text-dim);align-self:center;margin-right:2px';
  wrap.appendChild(lbl);
  var hasNone = members.some(function(m){ return !(m.region || '').trim() && !m.deleted; }); // v420: 未設定も選べるように
  var chips = ['__ALL__'].concat(regions).concat(hasNone ? ['__NONE__'] : []);
  chips.forEach(function(r){
    var isAll = (r === '__ALL__');
    var active = isAll ? (regionFilter === '') : (regionFilter === r);
    var chip = document.createElement('div');
    chip.textContent = isAll ? '📍全地域' : (r === '__NONE__' ? '未設定' : r);
    chip.style.cssText = 'font-size:11px;padding:3px 10px;border-radius:10px;cursor:pointer;border:1px solid ' + (active?'#FF87B3':'var(--border)') + ';background:' + (active?'#FF87B3':'transparent') + ';color:' + (active?'#fff':'var(--text-dim)');
    // v518: 922-4 地域を切り替えたら系列フォーカスも解除（フォーカスの薄暗が残り「全地域に戻しても暗いまま」になっていた。
    //        選んだ地域の人が別系列だと0.6に沈み「選んだ地域が強調されない」原因にもなっていた）
    chip.onclick = function(){ regionFilter = isAll ? '' : r; window._pcFocusLineage = ''; renderCurrentView(); setTimeout(applyRegionDim, 160); };
    wrap.appendChild(chip);
  });
  return true;
}
function applyRegionDim() { _applyMapDims(); }
// v450: カテゴリ絞り込み×地域絞り込みを1つの処理で同時適用。
// 従来は別々の関数がそれぞれopacityを書いていたため、後から走った方が先の薄暗を消していた
// （研修生で絞り込んでも保存・再描画のたびに全員明るく戻る／該当0人でも強調が残るバグの真因）
function _applyMapDims() {
  var catF = (typeof mapCatFilter !== 'undefined') ? mapCatFilter : '';
  var regF = (typeof regionFilter !== 'undefined') ? regionFilter : '';
  // v484: 判定用のIDマップは毎パス最新のメンバーから作り直す。
  //        _findMemberのキャッシュ経由だと、キャッシュが古い瞬間に「編集前の情報」で
  //        強調判定される（該当外の人が明るいまま残る）バグの温床だった。
  //        表示中のMAP（現状/理想）を優先しつつ、DOMに残るもう片方のツリーも解決できるよう補完。
  var _dimMap9 = null;
  var _findC9 = function(mid) {
    if (!_dimMap9) {
      _dimMap9 = {};
      var mt9 = (typeof currentView !== 'undefined' && currentView === 'ideal') ? 'ideal' : 'current';
      var mt8 = mt9 === 'ideal' ? 'current' : 'ideal';
      composeMergedInto(membersForMap(mt8), mt8).forEach(function(x) { _dimMap9[x.id] = x; });
      composeMergedInto(membersForMap(mt9), mt9).forEach(function(x) { _dimMap9[x.id] = x; });
    }
    return _dimMap9[mid] || null;
  };
  // PC組織図ノード（SVG）
  var nodes = document.querySelectorAll('.oval-node');
  var _lin9 = (typeof window !== 'undefined' && window._pcFocusLineage) || ''; // v438: 系列フォーカスと両立
  for (var i=0;i<nodes.length;i++){
    var r = normalizeRegionValue(nodes[i].getAttribute('data-region')); // v496: エイリアス（愛知⇄名古屋等）も正規化して判定（922-3）
    var ok = !regF || (regF === '__NONE__' ? !r : (r === normalizeRegionValue(regF)));
    if (ok && catF) {
      var mN = _findC9(nodes[i].getAttribute('data-mid'));
      ok = !!(mN && memberMatchesFilter(mN, catF));
    }
    var _nl9 = nodes[i].getAttribute('data-lineage');
    var _fOk9 = (!_lin9 || _nl9 === _lin9 || _nl9 === '');
    var _out9 = nodes[i].classList && nodes[i].classList.contains('is-out'); // v539: OUTは当月ゴースト表示（薄いまま）
    nodes[i].style.opacity = !ok ? '0.22' : (_fOk9 ? (_out9 ? '0.5' : '1') : (_out9 ? '0.3' : '0.6'));
    // v518: 922-3 活動中（脈打ち＝opacityアニメ）や研修中・フレッシュの発光アニメは style.opacity より優先されるため、
    //        他地域なのに明るく光って「選んだ地域より目立つ」状態だった。クラス（!important＋アニメ停止）で確実に薄くする
    if (nodes[i].classList) {
      nodes[i].classList.toggle('map-dim', !ok);
      nodes[i].classList.toggle('map-unfocus', ok && !_fOk9);
    }
  }
  // モバイルツリーカード（HTML）※結合ノードも合成リストで解決
  var cards = document.querySelectorAll('.nc[data-cid]');
  for (var j=0;j<cards.length;j++){
    var m = _findC9(cards[j].getAttribute('data-cid'));
    var rr = normalizeRegionValue((m && m.region) ? m.region : ''); // v496: エイリアスも正規化（922-3）
    var ok2 = !regF || (regF === '__NONE__' ? !rr : (rr === normalizeRegionValue(regF)));
    if (ok2 && catF) ok2 = !!(m && memberMatchesFilter(m, catF));
    cards[j].style.opacity = ok2 ? '' : '0.3';
  }
}
// 地域チップを指定コンテナに描画（モバイル用・都度クリア）
function buildRegionChipsInto(members, containerId) {
  var wrap = document.getElementById(containerId);
  if (!wrap) return;
  wrap.innerHTML = '';
  var ok = buildRegionFilter(members, wrap);
  wrap.style.display = ok ? 'flex' : 'none';
}
// ── 地域入力（プルダウン＋自由入力） ──
var REGION_PRESETS = ['東京','大阪','福岡','名古屋','熊本','大分','北九州'];
// 地域の表記ゆれ統一（愛知・愛知県 → 名古屋）
var REGION_ALIASES = { '愛知':'名古屋', '愛知県':'名古屋' };
function normalizeRegionValue(r) {
  r = (r || '').trim();
  return REGION_ALIASES[r] || r;
}
// 既存メンバーの地域を統一。変換が発生したら true
function migrateRegions() {
  var changed = false;
  [state.members, state.idealMembers].forEach(function(arr){
    if (!arr) return;
    arr.forEach(function(m){
      if (!m.region) return;
      var nr = normalizeRegionValue(m.region);
      if (nr !== m.region) { m.region = nr; changed = true; }
    });
  });
  return changed;
}
function onRegionSelChange() {
  var sel = document.getElementById('fRegionSel');
  var inp = document.getElementById('fRegion');
  if (!sel || !inp) return;
  if (sel.value === '__other__') {
    if (REGION_PRESETS.indexOf(inp.value) >= 0) inp.value = ''; // preset値ならクリア
    inp.style.display = '';
    inp.focus();
  } else {
    inp.value = sel.value; // preset / 未設定 を反映（保存元は #fRegion）
    inp.style.display = 'none';
  }
}
function syncRegionSelect(region) {
  var sel = document.getElementById('fRegionSel');
  var inp = document.getElementById('fRegion');
  if (!sel || !inp) return;
  region = (region || '').trim();
  if (region === '') { sel.value = ''; inp.value = ''; inp.style.display = 'none'; }
  else if (REGION_PRESETS.indexOf(region) >= 0) { sel.value = region; inp.value = region; inp.style.display = 'none'; }
  else { sel.value = '__other__'; inp.value = region; inp.style.display = ''; }
}

// ── カテゴリ絞り込み（メンバータブを現状に統合）──
var mapCatFilter = '';
// IDマップで O(1) 検索（数百人規模のO(n²)対策）。配列の差し替え/件数変化で再構築
var _memMap = null, _memMapSrc = null, _memMapN = -1;
function _findMember(mid){
  var ms = state.members || [];
  if (!_memMap || _memMapSrc !== ms || _memMapN !== ms.length) {
    _memMap = {}; _memMapSrc = ms; _memMapN = ms.length;
    for (var i = 0; i < ms.length; i++) _memMap[ms[i].id] = ms[i];
  }
  return _memMap[mid] || null;
}
// 絞り込み用：結合（MG_）ノードも含めた合成リストから探す（結合メンバーが誤って薄暗くなるのを防ぐ）
function _findMemberComposed(mid){
  if (!/^MG_/.test(mid)) return _findMember(mid);
  var list = composeMergedInto(membersForMap('current'), 'current');
  for (var i=0;i<list.length;i++){ if (list[i].id===mid) return list[i]; }
  return null;
}
function buildMapCatChips(members) {
  var wrap = document.getElementById('mapCatChips');
  var pcWrap = document.getElementById('pcMapCatChips'); // v471: PC版にも同じ絞り込みバー
  if (!wrap && !pcWrap) return;
  var own = (members || []).filter(function(m){ return !m.deleted; });
  var cAll = own.length, cTr = 0, cFr = 0, cBr = 0;
  own.forEach(function(m){
    if (memberMatchesFilter(m,'trainee')) cTr++;
    if (memberMatchesFilter(m,'fresh')) cFr++;
    if (memberMatchesFilter(m,'br')) cBr++;
  });
  var defs = [['','すべて',cAll,'#2CE5B8'],['trainee','研修生',cTr,'#FFB454'],['fresh','フレッシュ',cFr,'#4ADE80'],['br','BR',cBr,'#5AD7FF']];
  var html = defs.map(function(d){
    var active = (mapCatFilter === d[0]);
    return '<span class="mc-chip" onclick="setMapCatFilter(\'' + d[0] + '\')" style="border-color:' + (active?d[3]:'var(--border)') + ';background:' + (active?d[3]:'transparent') + ';color:' + (active?'#000':'var(--text-dim)') + '">' + d[1] + ' ' + d[2] + '</span>';
  }).join('');
  // v508: 「誕生日」チップは常時表示（0人はグレー）。タップで一覧シート（該当者がいれば強調も）
  var cBd = 0;
  own.forEach(function(m){ if (typeof _bdayIn30 === 'function' && _bdayIn30(m) !== null) cBd++; });
  var bdA = (mapCatFilter === 'bday'), bdCol = '#FF87B3';
  html += '<span class="mc-chip" onclick="mapBdayChipTap()" style="display:inline-flex;align-items:center;gap:3px;border-color:' + (bdA?bdCol:'var(--border)') + ';background:' + (bdA?bdCol:'transparent') + ';color:' + (bdA?'#000':(cBd>0?'#FF5D8F':'var(--text-dim)')) + '">' + icn('cake') + '誕生日 ' + cBd + '</span>';
  // v471: QBR（LOI〜Q4）はドロップダウンで選択して絞り込み
  var QBR_TITLES = ['LOI','Q2','Q3','Q4'];
  var qbrActive = (mapCatFilter || '').indexOf('qbr:') === 0;
  var qbrSel = qbrActive ? mapCatFilter.slice(4) : '';
  var qbrCol = '#F6C744';
  html += '<select class="mc-chip" onchange="setMapCatFilter(this.value)" title="QBR（LOI〜Q4のタイトルで絞り込み）"'
    + ' style="-webkit-appearance:none;appearance:none;outline:none;border-color:' + (qbrActive?qbrCol:'var(--border)') + ';background:' + (qbrActive?qbrCol:'transparent') + ';color:' + (qbrActive?'#000':'var(--text-dim)') + '">'
    + '<option value="">' + (qbrActive ? 'QBR解除' : 'QBR ▾') + '</option>'
    + QBR_TITLES.map(function(t){
        var n = 0;
        own.forEach(function(m){ if ((m.title||'').trim() === t) n++; });
        return '<option value="qbr:' + t + '"' + (qbrSel === t ? ' selected' : '') + '>' + t + ' ' + n + '</option>';
      }).join('')
    + '</select>';
  if (wrap) wrap.innerHTML = html;
  if (pcWrap) {
    pcWrap.innerHTML = html;
    pcWrap.classList.toggle('show', (typeof _pcView === 'undefined') || _pcView === 'tree');
  }
}
function setMapCatFilter(f) { mapCatFilter = f; renderCurrentView(); setTimeout(applyMapCatDim, 180); }
function applyMapCatDim() { _applyMapDims(); } // v450: 地域と統合（_applyMapDims）


// ── テーマ切替 ──
function setTheme(theme) {
  if (theme === 'light') document.body.classList.add('light');
  else document.body.classList.remove('light');
  try { localStorage.setItem('gm_theme', theme); } catch(e){}
  syncThemeButtons();
  // PC MAPを再描画（SVG内の色がテーマ依存のため）
  if (isPCMode() && (currentView === 'current' || currentView === 'ideal')) {
    renderPCMap(currentView);
  }
}
function syncThemeButtons() {
  var isLight = document.body.classList.contains('light');
  var d = document.getElementById('rbThemeDark');
  var l = document.getElementById('rbThemeLight');
  if (d) d.classList.toggle('sel', !isLight);
  if (l) l.classList.toggle('sel', isLight);
}
function initTheme() {
  var t = 'dark';
  try { t = localStorage.getItem('gm_theme') || 'dark'; } catch(e){}
  if (t === 'light') document.body.classList.add('light');
  syncThemeButtons();
}
// ── メンバータブ 表示/非表示（MAPとほぼ同じ内容のため任意で畳める） ──
function membersTabHidden() {
  try { return localStorage.getItem('gm_hideMembersTab') === '1'; } catch(e){ return false; }
}
function applyMembersTabVisible() {
  var hide = membersTabHidden();
  var it = document.querySelector('.pcs-item[data-view="members"]');
  if (it) it.style.display = hide ? 'none' : '';
  // ※モバイル下部ナビにメンバータブは存在しない（☰メニュー内で openMobileMenu が同フラグを参照）
  // 非表示中に開いていたら MAP に戻す
  if (hide && typeof currentView !== 'undefined' && currentView === 'members') switchView('current');
  var on = document.getElementById('rbMembersOn'), off = document.getElementById('rbMembersOff');
  if (on) on.classList.toggle('sel', !hide);
  if (off) off.classList.toggle('sel', hide);
}
function setMembersTabVisible(v) {
  try { localStorage.setItem('gm_hideMembersTab', v ? '0' : '1'); } catch(e){}
  applyMembersTabVisible();
}

// ── プロフィール設定 ──
var _profileMandatory = false; // 必須項目未入力 → 強制入力モード（閉じられない）
var OWNER_UID = 'j2DPDAccCygHmR9i5K3bTvHnH0V2'; // 永久管理者（ルールと一致させること）
var OWNER_UIDS = [OWNER_UID, 'E4WT7EHai5c6WANUgASz42Euu1y1']; // v669: オーナー（馬越さんを追加）。firestore.rules の isOwnerUid と一致させること
function isOwnerUid(uid) { return OWNER_UIDS.indexOf(uid) >= 0; }

// 現在のユーザーが管理者か（オーナー or role:'admin'）
function isCurrentAdmin() {
  return !!currentUser && (isOwnerUid(currentUser.uid) || currentUser.role === 'admin');
}

// ===== アカウント管理（管理者のみ） =====
var _adminUsers = [];
function openAdminPanel() {
  if (!isCurrentAdmin()) { toast('権限がありません'); return; }
  closeProfileModal(null);
  document.getElementById('adminPanel').classList.add('open');
  loadAdminUsers();
}
function closeAdminPanel() {
  document.getElementById('adminPanel').classList.remove('open');
}
function loadAdminUsers() {
  var body = document.getElementById('adminBody');
  if (body) body.innerHTML = '<div class="ev-empty">読み込み中...</div>';
  fsGetCol('users').then(function(list) {
    _adminUsers = list || [];
    renderAdminList();
  }).catch(function() {
    if (body) body.innerHTML = '<div class="ev-empty">読み込みに失敗しました（権限をご確認ください）</div>';
  });
}
function _adminFindUser(uid) {
  for (var i=0;i<_adminUsers.length;i++) if (_adminUsers[i].id === uid) return _adminUsers[i];
  return null;
}
// v586: データ使用状況レポートは廃止（他のユーザーのデータを読むため。ルールで管理者も読めなくした）
function _adminScopedUsers() {
  var owner = !!(currentUser && isOwnerUid(currentUser.uid));
  var myUnion = (currentUser && currentUser.union) ? currentUser.union : '';
  return owner ? _adminUsers : _adminUsers.filter(function(u){ return (u.union||'') === myUnion; });
}
function renderAdminList() {
  var body = document.getElementById('adminBody');
  if (!body) return;
  var q = ((document.getElementById('adminSearch')||{}).value||'').toLowerCase();
  var scoped = _adminScopedUsers();
  var list = scoped.filter(function(u) {
    if (!q) return true;
    return ((u.name||'')+(u.union||'')+(u.area||'')+(u.email||'')+(u.upRuby||'')+(u.upBd||'')).toLowerCase().indexOf(q) >= 0;
  });
  var pending = list.filter(function(u){ return u.status === 'pending'; });
  var others  = list.filter(function(u){ return u.status !== 'pending'; });
  others.sort(function(a,b) {
    function rank(u){ return isOwnerUid(u.id) ? 0 : (u.role==='admin' ? 1 : 2); }
    var ra=rank(a), rb=rank(b);
    if (ra!==rb) return ra-rb;
    return (a.name||'').localeCompare(b.name||'');
  });
  var cnt = document.getElementById('adminCount');
  var _pvNo = scoped.filter(function(u){ return _pvNeed(u); }).length; // v668: 未同意の人数
  if (cnt) cnt.textContent = scoped.length + '人' + (pending.length ? '・承認待ち'+pending.length : '') + (_pvNo ? '・未同意'+_pvNo : '');
  var html = '';
  if (pending.length) {
    html += '<div style="padding:12px 14px 4px;font-size:12px;font-weight:700;color:#FFB454">⏳ 承認待ち（' + pending.length + '）</div>';
    html += pending.map(adminPendingRowHtml).join('');
    html += '<div style="height:6px;border-bottom:1px solid var(--border);margin-bottom:6px"></div>';
  }
  if (!others.length && !pending.length) { body.innerHTML = '<div class="ev-empty">該当ユーザーがいません</div>'; return; }
  html += others.map(adminRowHtml).join('');
  body.innerHTML = html;
}
function adminPendingRowHtml(u){
  var uid = u.id;
  var name = evEsc(u.name || '(名前未設定)');
  var sub  = evEsc([u.union, u.area].filter(Boolean).join(' / '));
  var sub2 = evEsc([u.upRuby ? ('UPルビー:'+u.upRuby) : '', u.upBd ? ('UPBD:'+u.upBd) : ''].filter(Boolean).join(' / '));
  var email= evEsc(u.email || '');
  return '<div class="adm-row" style="border-left:3px solid #FFB454">'
    + '<div class="adm-main"><div class="adm-name">' + name + ' <span class="adm-badge" style="background:rgba(255,180,84,.15);color:#FFB454">承認待ち</span>' + _pvBadge(u) + '</div>'
    + (sub  ? '<div class="adm-sub">' + sub  + '</div>' : '')
    + (sub2 ? '<div class="adm-sub">' + sub2 + '</div>' : '')
    + (email? '<div class="adm-sub" style="opacity:.7">' + email + '</div>' : '')
    + '</div><div class="adm-actions">'
    + '<button class="adm-btn on" onclick="adminApprove(\'' + uid + '\')">承認</button>'
    + '<button class="adm-btn" style="border-color:#FF5D73;color:#FF5D73" onclick="adminReject(\'' + uid + '\')">却下</button>'
    + '</div></div>';
}
function adminApprove(uid){
  var u=_adminFindUser(uid); if(!u) return;
  u.status='active'; u.approvedBy=currentUser.uid; u.approvedAt=new Date().toISOString();
  fsSet('users/'+uid,{status:'active',approvedBy:u.approvedBy,approvedAt:u.approvedAt})
    .then(function(){ toast('承認しました ✓'); }).catch(function(e){ toast('承認に失敗しました'); console.error(e); });
  renderAdminList();
}
function adminReject(uid){
  var u=_adminFindUser(uid); if(!u) return;
  if(!confirm('この登録申請を却下しますか？\n' + (u.name||'') + '（' + (u.email||'') + '）')) return;
  u.status='disabled'; u.disabledBy=currentUser.uid; u.disabledAt=new Date().toISOString();
  fsSet('users/'+uid,{status:'disabled',disabledBy:u.disabledBy,disabledAt:u.disabledAt})
    .then(function(){ toast('却下しました'); }).catch(function(e){ toast('失敗しました'); console.error(e); });
  renderAdminList();
}
function adminRowHtml(u) {
  var uid = u.id;
  var isOwner = isOwnerUid(uid);
  var disabled = u.status === 'disabled';
  var roleBadge = isOwner ? '<span class="adm-badge owner">オーナー</span>'
                 : (u.role==='admin' ? '<span class="adm-badge admin">管理者</span>' : '');
  var statusBadge = disabled ? '<span class="adm-badge dis">無効</span>' : '';
  var name = evEsc(u.name || '(名前未設定)');
  var sub  = evEsc([u.union, u.area].filter(Boolean).join(' / '));
  var sub2 = evEsc([u.upRuby ? ('UPルビー:'+u.upRuby) : '', u.upBd ? ('UPBD:'+u.upBd) : ''].filter(Boolean).join(' / '));
  var email = evEsc(u.email || '');
  var actions;
  if (isOwner) {
    actions = '<div class="adm-note">オーナー<br>（変更不可）</div>';
  } else {
    actions = '<button class="adm-btn' + (disabled ? ' on' : '') + '" onclick="adminToggleStatus(\'' + uid + '\')">' + (disabled ? '有効化' : '無効化') + '</button>'
            + '<button class="adm-btn' + (u.role==='admin' ? ' admin' : '') + '" onclick="adminToggleRole(\'' + uid + '\')">' + (u.role==='admin' ? '管理者解除' : '管理者にする') + '</button>';
  }
  return '<div class="adm-row' + (disabled ? ' is-dis' : '') + '">'
    + '<div class="adm-main"><div class="adm-name">' + name + ' ' + roleBadge + statusBadge + _pvBadge(u) + '</div>'
    + (sub  ? '<div class="adm-sub">' + sub  + '</div>' : '')
    + (sub2 ? '<div class="adm-sub">' + sub2 + '</div>' : '')
    + (email? '<div class="adm-sub" style="opacity:.7">' + email + '</div>' : '')
    + '</div><div class="adm-actions">' + actions + '</div></div>';
}
function adminToggleStatus(uid) {
  if (isOwnerUid(uid)) { toast('オーナーは変更できません'); return; }
  var u = _adminFindUser(uid); if (!u) return;
  var disable = u.status !== 'disabled';
  if (!confirm((disable ? 'このアカウントを無効化（全データ閲覧不可）にしますか？' : 'このアカウントを有効化しますか？') + '\n' + (u.name||'') + '（' + (u.email||'') + '）')) return;
  u.status = disable ? 'disabled' : 'active';
  u.disabledAt = disable ? new Date().toISOString() : '';
  u.disabledBy = disable ? currentUser.uid : '';
  fsSet('users/' + uid, { status: u.status, disabledAt: u.disabledAt, disabledBy: u.disabledBy })
    .then(function(){ toast(disable ? '無効化しました' : '有効化しました'); })
    .catch(function(){ toast('変更に失敗しました'); });
  renderAdminList();
}
function adminToggleRole(uid) {
  if (isOwnerUid(uid)) { toast('オーナーは変更できません'); return; }
  var u = _adminFindUser(uid); if (!u) return;
  var makeAdmin = u.role !== 'admin';
  if (!confirm((makeAdmin ? 'このアカウントを共同管理者にしますか？' : '共同管理者を解除しますか？') + '\n' + (u.name||'') + '（' + (u.email||'') + '）')) return;
  u.role = makeAdmin ? 'admin' : 'member';
  u.roleSetBy = currentUser.uid;
  u.roleSetAt = new Date().toISOString();
  fsSet('users/' + uid, { role: u.role, roleSetBy: u.roleSetBy, roleSetAt: u.roleSetAt })
    .then(function(){ toast(makeAdmin ? '共同管理者にしました' : '管理者を解除しました'); })
    .catch(function(){ toast('変更に失敗しました'); });
  renderAdminList();
}

// ── ユニオン一覧（選択制）＋デフォルトUPBD（ユニオン管理者） ──
var UNION_LIST = [
  { name:'GRANT',        upbd:'木村妃咲' },
  { name:'PRESTO',       upbd:'中原賢三' },
  { name:'LIEN',         upbd:'小川拓郎' },
  { name:'BEYOND',       upbd:'堀田めぐみ' },
  { name:'FELIN',        upbd:'平井凛太郎' },
  { name:'FORMULA',      upbd:'木下文貴' },
  { name:'REVITALIZE',   upbd:'藤原拓晶' },
  { name:'INFLUENCE',    upbd:'高島健佑' },
  { name:'BASE ANTARES', upbd:'馬越雅哉' },
  { name:'BASE REVE',    upbd:'浦田美沙子' },
  { name:'LIEN LOAD',    upbd:'松田郁愛' },
  { name:'DEFI',         upbd:'中原賢三' },
  { name:'GRANDIR',      upbd:'嶽本尚希' },
  { name:'SFIDA',        upbd:'' },
  { name:'AMASIA',       upbd:'' },
  { name:'UPBD',         upbd:'渡邉寛' }
];
function unionOptionsHtml(placeholder) {
  var h = '<option value="">' + (placeholder || 'ユニオンを選択') + '</option>';
  UNION_LIST.forEach(function(u){
    h += '<option value="' + u.name + '" data-upbd="' + u.upbd + '">' + u.name + '</option>';
  });
  return h;
}
// v393: 活動地域の選択肢はメンバー編集の「地域」と同じリスト（REGION_PRESETS）＋その他（自由入力）
function areaOptionsHtml(ph) {
  var h = '<option value="">' + (ph || '活動地域を選択') + '</option>';
  REGION_PRESETS.forEach(function(a){ h += '<option value="' + a + '">' + a + '</option>'; });
  h += '<option value="__other__">その他（自由入力）</option>';
  return h;
}
// その他（自由入力）が選ばれたら入力を促して選択肢に追加
function _areaOtherHandler(ev) {
  var el2 = ev.target;
  if (el2.value !== '__other__') return;
  var v = prompt('活動地域を入力してください');
  v = (v || '').trim();
  if (!v) { el2.value = ''; return; }
  _areaSelectSet(el2, v);
}
// select要素へ選択肢を流し込む（未流し込みのときだけ）
function populateUnionSelects() {
  var targets = [
    { id:'signupUnion',  ph:'所属ユニオンを選択' },
    { id:'profileUnion', ph:'ユニオンを選択' }
  ];
  targets.forEach(function(t){
    var s = document.getElementById(t.id);
    if (s && s.tagName === 'SELECT' && s.options.length <= 1) s.innerHTML = unionOptionsHtml(t.ph);
  });
  // v392: 活動地域セレクトにも流し込み（v393: その他=自由入力対応）
  ['signupArea', 'profileArea'].forEach(function(idn){
    var a = document.getElementById(idn);
    if (a && a.tagName === 'SELECT' && a.options.length <= 1) {
      a.innerHTML = areaOptionsHtml('活動地域を選択');
      a.addEventListener('change', _areaOtherHandler);
    }
  });
}
// v392: リストに無い既存値（自由入力時代の値）も選択肢に足してから選択する
function _areaSelectSet(el2, val) {
  if (!el2) return;
  if (el2.tagName === 'SELECT' && val) {
    var has = false;
    for (var i = 0; i < el2.options.length; i++) { if (el2.options[i].value === val) { has = true; break; } }
    if (!has) { var op = document.createElement('option'); op.value = val; op.textContent = val; el2.appendChild(op); }
  }
  el2.value = val || '';
}
// ユニオン選択時：デフォルトで管理者名をUPBD欄へ（あとから編集可）
function onUnionSelect(sel, upbdId) {
  if (!sel) return;
  var opt = sel.options[sel.selectedIndex];
  var mgr = opt ? (opt.getAttribute('data-upbd') || '') : '';
  var t = document.getElementById(upbdId);
  if (t) t.value = mgr;
}

// プロフィールが必須4項目を満たしているか
// （unionSelectedV2＝選択制ユニオンで選び直したか。旧ユーザーは強制で選び直させる）
function profileComplete(u) {
  u = u || currentUser || {};
  return !!(u.union && u.area && u.upRuby && u.upBd && u.unionSelectedV2);
}
// ログイン後ゲート：未入力なら強制入力モーダルを開く
function enforceProfileGate() {
  if (!currentUser) return;
  if (profileComplete(currentUser)) { _profileMandatory = false; return; }
  _profileMandatory = true;
  openProfileModal();
}

function openProfileModal() {
  if (!currentUser) return;
  var el = function(id){ return document.getElementById(id); };
  if (el('profileName')) el('profileName').value = currentUser.name || '';
  if (el('profileOrg'))  el('profileOrg').value  = currentUser.org  || '';
  if (el('profileArea')) { populateUnionSelects(); _areaSelectSet(el('profileArea'), currentUser.area || ''); } // v392: 選択式
  populateUnionSelects();
  // 選択制ユニオン：既に選び直し済みのユーザーだけ現在値を復元。旧ユーザーは未選択にして選び直しを強制。
  if (el('profileUnion')) el('profileUnion').value = currentUser.unionSelectedV2 ? (currentUser.union || '') : '';
  if (el('profileUpRuby'))el('profileUpRuby').value = currentUser.upRuby || '';
  if (el('profileUpBd')) el('profileUpBd').value  = currentUser.upBd || '';
  var accEmail = el('profileAccountEmail');
  if (accEmail) {
    var em = currentUser.email || (auth && auth.currentUser && auth.currentUser.email) || '';
    accEmail.textContent = em ? ('ログイン中：' + em) : '';
  }
  var note = el('profileMandatoryNote'); if (note) note.style.display = _profileMandatory ? '' : 'none';
  var cancel = el('profileCancelBtn'); if (cancel) cancel.style.display = _profileMandatory ? 'none' : '';
  var title = el('profileModalTitle'); if (title) title.textContent = _profileMandatory ? 'プロフィール入力（必須）' : 'プロフィール設定';
  var perr = el('profileError'); if (perr) perr.style.display = 'none';
  var adm = el('profileAdminWrap'); if (adm) adm.style.display = (!_profileMandatory && isCurrentAdmin()) ? '' : 'none';
  try { _fbSyncEntry(); } catch (eFb) {} // v585
  syncThemeButtons();
  if (typeof applyMembersTabVisible === 'function') applyMembersTabVisible();
  var m = document.getElementById('profileModal');
  if (m) m.classList.add('open');
}

function closeProfileModal(e) {
  if (e && e.target !== document.getElementById('profileModal')) return;
  if (_profileMandatory) { // 必須未入力の間は閉じさせない
    if (e) return;
    var perr = document.getElementById('profileError');
    if (perr) { perr.textContent = '必須項目を入力してください'; perr.style.display = ''; }
    return;
  }
  var m = document.getElementById('profileModal');
  if (m) m.classList.remove('open');
}

function clearMapData() {
  if (!state.isEditor) { toast('編集権限がありません'); return; }
  var mo = state.currentMonth || (typeof currentMonthStr === 'function' ? currentMonthStr() : '');
  var cnt = (state.members || []).filter(function(m){ return !m.deleted; }).length;
  if (!confirm('【組織MAPをクリア】\n\n' + mo + ' の組織MAP（現状・理想のメンバー ' + cnt + '人・OL記録）を全て削除します。\nテストデータの削除に使ってください。\n\n※この操作は取り消せません。続けますか？')) return;
  if (!confirm('本当に削除してよろしいですか？\n\nもう一度確認：' + mo + ' のメンバー ' + cnt + '人を全て消します。')) return;
  state.members = [];
  state.idealMembers = [];
  state.freshData = {};
  window._skipMergeOnce = true; // 意図的な全消し：共同編集マージで復活させない
  if (typeof autoSave === 'function') autoSave();
  if (typeof closeProfileModal === 'function') closeProfileModal(null);
  if (typeof switchView === 'function') switchView('current'); else if (typeof renderCurrentView === 'function') renderCurrentView();
  toast('組織MAPをクリアしました ');
}
function saveProfile() {
  if (!currentUser || !currentUser.uid) return;
  var el = function(id){ return ((document.getElementById(id)||{}).value||'').trim(); };
  var name  = el('profileName');
  var org   = el('profileOrg');
  var union = el('profileUnion');
  var area  = el('profileArea');
  var upRuby= el('profileUpRuby');
  var upBd  = el('profileUpBd');
  var perr  = document.getElementById('profileError');
  // 必須4項目チェック
  if (!union || !area || !upRuby || !upBd) {
    if (perr) { perr.textContent = '所属ユニオン・活動地域・UPルビー・UPBD は必須です'; perr.style.display = ''; }
    return;
  }
  currentUser.name = name; currentUser.org = org;
  currentUser.area = area; currentUser.union = union;
  currentUser.upRuby = upRuby; currentUser.upBd = upBd;
  currentUser.unionSelectedV2 = true; // 選択制ユニオンで確定済みの印

  // ヘッダー更新
  var logo = document.getElementById('appLogo');
  if (logo) logo.textContent = currentUser.org || 'NAVIGATOR';
  var nameEl = document.getElementById('appUserName');
  if (nameEl) {
    var infoText = currentUser.name;
    if (currentUser.area)  infoText += ' | ' + currentUser.area;
    if (currentUser.union) infoText += ' | ' + currentUser.union;
    nameEl.textContent = infoText;
    nameEl.style.display = '';
  }

  // Firestoreに保存（role/status は本人が触らない＝送らない）
  if (USE_FIREBASE && currentUser.uid) {
    fsSet('users/' + currentUser.uid, {
      name: name, displayName: name, org: org, area: area, union: union, // v670: displayName も（ATTACK LIST・GOAL SETTING は displayName を優先して表示するため）
      upRuby: upRuby, upBd: upBd, unionSelectedV2: true,
      email: currentUser.email, uid: currentUser.uid,
      registrationComplete: true, updatedAt: new Date().toISOString()
    }).then(function(){ toast('プロフィールを保存しました ✓'); });
  }
  _profileMandatory = false;
  closeProfileModal(null);
}

