// v501: やる気レベル＝色分き線画アイコン（1=緑の芽・2=オレンジの稲妻・3=赤の炎）
var MORALE_COLORS = ['', '#4ADE80', '#FFB454', '#FF5D73'];
var MORALE_ICON_NAMES = ['', 'sprout', 'zap', 'flame'];
var MORALE_LABELS = ['', 'パヤパヤ', 'やる気', '死ぬ気'];
function moraleLv(level) { return Math.max(1, Math.min(parseInt(level, 10) || 1, 3)); }
function moraleLabel(level) { return MORALE_LABELS[moraleLv(level)]; }
// v510: やる気＝グラデーションの丸バッジ＋白い絵柄（小さくても色と形で判別できる）
var MORALE_GRAD = ['', ['#4ADE80', '#15803D'], ['#FDBA3B', '#EA580C'], ['#FB7185', '#DC2626']];
var MORALE_GLYPH = ['',
  '<path d="M11 21.5v-8.2" stroke="#fff" stroke-width="3.2" stroke-linecap="round" fill="none"/><path fill="#fff" d="M10.4 14.4C10.6 9 7 5.6 1.6 5.8 1.4 11 5 14.6 10.4 14.4z"/><path fill="#fff" d="M11.8 12.2C11.6 7.6 14.6 4.2 19.6 4.2 19.8 8.9 16.7 12.2 11.8 12.2z"/>',
  '<path fill="#fff" d="M13.6 1.5 4 13.4h6.4L9.2 22.5l9.8-12.3h-6.6z"/>',
  '<path fill="#fff" d="M12 1.2c.8 3.5 2.6 5.6 4.6 7.5 2 1.8 3.4 3.9 3.4 6.5a8 8 0 01-16 0c0-2.2.9-4 2.2-5.4.3 1.8 1.2 3.1 2.5 3.9-.6-4 .7-8.6 3.3-12.5z"/>'
];
function moraleFill(lv, gid) {
  return '<defs><linearGradient id="' + gid + '" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="' + MORALE_GRAD[lv][0] + '"/><stop offset="1" stop-color="' + MORALE_GRAD[lv][1] + '"/></linearGradient></defs>'
    + '<circle cx="12" cy="12" r="11.2" fill="url(#' + gid + ')" stroke="#fff" stroke-width="1.4"/>'
    + '<g transform="translate(4.2 4.2) scale(0.65)">' + MORALE_GLYPH[lv] + '</g>';
}
function moraleIcon(level, px) {
  var lv = moraleLv(level);
  var sz = px ? px + 'px' : '1.4em';
  return '<svg class="lic mor" viewBox="0 0 24 24" style="width:' + sz + ';height:' + sz + '"><title>' + MORALE_LABELS[lv] + '</title>' + moraleFill(lv, 'mgH' + lv) + '</svg>';
}
function icn(name, style) {
  if (name === 'trash') style = 'color:var(--red)' + (style ? ';' + style : ''); // v509: ゴミ箱は常に赤
  return '<svg class="lic" viewBox="0 0 24 24"' + (style ? ' style="' + style + '"' : '') + '>' + (ICONS[name] || '') + '</svg>';
}
