  try { document.body.setAttribute('data-v', v); } catch (eDv) {}
  if (v !== 'stats') document.body.classList.remove('dt-lf', 'dt-rgx'); // v646
  try { if (typeof mxOrbitClose === 'function') mxOrbitClose(); } catch (eMo) {} // v659 // v632: 左下の「‹ メニュー」を出すかの判定用
  if (v === 'current') setTimeout(function() { try { ckTrAuto(); } catch (eCk) {} }, 1500); // v623: MAPを開いた時に受付の研修記録を取り込む（1日1回）
  if (v !== 'ideal') { try { _p2BackHide(); } catch (eB) {} } // v575
  var _prevView = currentView;
  currentView = v;
  if (v !== 'plan') { _p2Pg = ''; _p2PgI = 0; try { document.body.classList.remove('ux-pg', 'ux-hub'); } catch (eUx) {} } // v593: PLANのページは離れたら入口へ
  try { if (typeof uxMemClose === 'function' && document.getElementById('uxMemPg')) uxMemClose(); } catch (eMc) {} // v597
  if (v !== 'plan') _p2MonYm = '';
  if (v !== 'stats') { _dtPg = ''; try { document.body.classList.remove('ux-dt'); } catch (eUd) {} } // v596
  else if (_prevView !== 'stats') { _dtMode = _dtPg ? 'ez' : 'full'; if (!DT_TABS.some(function(t) { return t[0] === _dtTab; })) _dtTab = 'trend'; } // v647: 分析は開いたらすぐ推移（タブ）
  try { _uxSync(); } catch (eUs) {}
  window._selectedCardId = null;
  if (v === 'menu') { try { _uxMenuView(); } catch (eMv) {} } // v595
  ['home','members','current','ideal','stats','ol','events','goals','month','plan','menu'].forEach(function(n) {
    var el = document.getElementById('view-'+n);
    if (el) el.style.display = (n===v ? '' : 'none');
  });
  // PC左サイドバー・モバイル下部ナビのactive切り替え
  var _mainTabs = ['home','current','events','stats'];
  Array.prototype.slice.call(document.querySelectorAll('.pcs-item, .mtab')).forEach(function(it) {
    var dv = it.getAttribute('data-view');
    // PCサイドバーでは理想MAPもMAPアイコンをアクティブに（現状/理想はツールバーで切替）
    var on = dv === v || (v === 'ideal' && dv === 'current');
    // モバイル：メンバー/OL/GOAL/今月などはメニュータブを点灯（現在地を見失わない）
    if (dv === 'more') on = (_mainTabs.indexOf(v) < 0 && v !== 'ideal');
    it.classList.toggle('active', on);
  });
  // v297: モバイルは予定タブを開いた瞬間、常に全画面の月カレンダー（タップ数最小化）。
  //       PCは前回モードを記憶。他タブへ移る時は全画面用の非表示を必ず解除（ナビ喪失防止）
  if (v === 'events' && typeof setEventsMode === 'function') setEventsMode(isPCMode() ? _evMode : 'calendar');
  else document.body.classList.remove('cal-fs');
