      + '<div class="rn-hd"><span class="rn-v">' + evEsc(n.v) + '</span>' + (i===0?'<span class="rn-new">NEW</span>':'') + '<span class="rn-d go-tnum">' + evEsc(n.d) + '</span></div>'
      + '<ul class="rn-ul">' + n.items.map(function(t){ return '<li>' + evEsc(t) + '</li>'; }).join('') + '</ul>'
