function _bdayDaysUntil(m) {
  if (!m || m.deleted || !m.birthday || (m.title || '').trim() === 'OUT') return null;
  var p = /^(\d{4})-(\d{2})-(\d{2})/.exec(m.birthday);
  if (!p) return null;
  var now = new Date();
  var t0 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  var next = new Date(now.getFullYear(), parseInt(p[2], 10) - 1, parseInt(p[3], 10));
  if (next < t0) next = new Date(now.getFullYear() + 1, parseInt(p[2], 10) - 1, parseInt(p[3], 10));
  return Math.round((next - t0) / 86400000);
}
function _bdayIn30(m) {
  var d = _bdayDaysUntil(m);
  return (d !== null && d <= 30) ? d : null;
}
function _bdayMD(m) {
  var p = /^\d{4}-(\d{2})-(\d{2})/.exec(m.birthday || '');
  return p ? (parseInt(p[1], 10) + '/' + parseInt(p[2], 10)) : '';
}
function _bdayTurnAge(m) {
  var p = /^(\d{4})-(\d{2})-(\d{2})/.exec(m.birthday || '');
  if (!p) return null;
  var now = new Date();
  var t0 = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  var next = new Date(now.getFullYear(), parseInt(p[2], 10) - 1, parseInt(p[3], 10));
  if (next < t0) next = new Date(now.getFullYear() + 1, parseInt(p[2], 10) - 1, parseInt(p[3], 10));
  return next.getFullYear() - parseInt(p[1], 10);
}
