// ── 先月からの変化（月次変化の自動検知）──
var mcExpanded = false;
function mcPrevMonth(cur) {
  var p = String(cur || '').split('.'); var y = parseInt(p[0],10), m = parseInt(p[1],10);
  if (!y || !m) return '';
  m--; if (m < 1) { m = 12; y--; }
  return y + '.' + String(m).padStart(2,'0');
}
function mcActRank(a) { return a==='S'?4:(a==='A'?3:(a==='B'?2:(a==='C'?1:0))); } // S>A(仕事辞める日確定=good)>B>C
function mcTitleRank(t) {
  t = (t || '').trim(); if (!t) return -1;
  var order = [];
  if (typeof TITLE_OPTIONS !== 'undefined') { ['研修生','BA','BR'].forEach(function(k){ (TITLE_OPTIONS[k]||[]).forEach(function(x){ order.push(x); }); }); }
  return order.indexOf(t);
}
function mcName(m) { return ((m.lastName||'') + (m.firstName||'')) || '(無名)'; }
function computeMonthlyChanges(prev, cur) {
  var prevById = {}, curById = {};
  prev.forEach(function(m){ if (!m.deleted) prevById[m.id] = m; });
  cur.forEach(function(m){ curById[m.id] = m; });
  var out = [];
  cur.forEach(function(m){
    var pm = prevById[m.id], nm = mcName(m);
    if (!pm) { out.push({ t: nm + ' が新加入 🎉', c:'good', pr:2 }); return; }
    if ((m.activity||'') !== (pm.activity||'')) {
      var worse = mcActRank(m.activity) < mcActRank(pm.activity);
      out.push({ t: nm + '：稼働 ' + (pm.activity||'-') + '→' + (m.activity||'-'), c: worse?'warn':'good', pr: worse?3:1 });
    }
    var pmo = pm.morale||1, cmo = m.morale||1;
    if (cmo < pmo) out.push({ t: nm + '：やる気ダウン ' + moraleLabel(pmo) + '→' + moraleLabel(cmo), c:'warn', pr:2 });
    else if (cmo > pmo) out.push({ t: nm + '：やる気アップ ' + moraleLabel(pmo) + '→' + moraleLabel(cmo), c:'good', pr:1 });
    // タイトル変化：B系（活動歴）は非表示。LOI/Q2/Q3/Q4の審査クリアと、BR昇格のみ表示
    var qSeries = ['LOI','Q2','Q3','Q4'];
    var ct = (m.title||'').trim(), pt = (pm.title||'').trim();
    if (ct !== pt) {
      var cCat = (typeof detectCategory==='function') ? detectCategory(ct) : '';
      var pCat = (typeof detectCategory==='function') ? detectCategory(pt) : '';
      var cQ = qSeries.indexOf(ct), pQ = qSeries.indexOf(pt);
      if (cCat === 'BR' && pCat !== 'BR') out.push({ t: nm + '：BR昇格 ' + pt + '→' + ct + ' 🎉🎉', c:'good', pr:3 });
      else if (pQ >= 0 && cQ >= 0 && cQ > pQ) out.push({ t: nm + '：審査クリア ' + pt + '→' + ct + ' 🎉', c:'good', pr:2 });
    }
  });
  prev.forEach(function(pm){ if (!pm.deleted && !curById[pm.id]) out.push({ t: mcName(pm) + ' が離脱', c:'warn', pr:2 }); });
  out.sort(function(a,b){ return b.pr - a.pr; });
  return out;
}
var _mcPrevCache = { key: '', members: null }; // 前月データはセッション内1回だけ取得（ホーム再描画のたびに読まない）
function renderMonthlyChanges() {
  var box = document.getElementById('homeChanges'); if (!box) return;
  // 共有MAP閲覧中は state.members が相手の組織＝自分の前月と比較すると嘘の変化が出るため表示しない
  if (typeof viewingOwnerUid !== 'undefined' && viewingOwnerUid) {
    box.innerHTML = '<div class="ck-empty">共有MAP閲覧中は表示されません<br><span>自分のMAPに戻ると再表示されます</span></div>';
    return;
  }
  var uid = (currentUser && currentUser.uid) ? currentUser.uid : (typeof eventsUid === 'function' ? eventsUid() : '');
  var prev = mcPrevMonth(state.currentMonth);
  if (!db || !uid || !prev) { box.innerHTML = '<div class="ck-empty">前月データがありません</div>'; return; }
  var _mcKey = uid + '|' + prev;
  var _mcFetch = (_mcPrevCache.key === _mcKey && _mcPrevCache.members !== null)
    ? Promise.resolve({ members: _mcPrevCache.members })
    : fsGet('maps/' + uid + '/months/' + prev + '_current').then(function(d){ _mcPrevCache = { key: _mcKey, members: (d && d.members) || [] }; return d; });
  _mcFetch.then(function(data) {
    var pm = (data && data.members) ? data.members : [];
    if (!pm.length) { box.innerHTML = '<div class="ck-empty">前月（' + prev + '）のデータがありません<br><span>月をまたいで使うと自動で変化が出ます</span></div>'; return; }
    var ch = computeMonthlyChanges(pm, (typeof gameActiveMembers === 'function' ? gameActiveMembers() : (state.members||[])));
    if (!ch.length) { box.innerHTML = '<div class="ck-empty">先月からの大きな変化はありません 👍</div>'; return; }
    var shown = mcExpanded ? ch : ch.slice(0, 6);
    var html = shown.map(function(x){ return '<div class="hi-item ' + x.c + '">' + evEsc(x.t) + '</div>'; }).join('');
    if (ch.length > 6) html += '<div class="ck-more" onclick="mcExpanded=!mcExpanded;renderMonthlyChanges()">' + (mcExpanded ? '閉じる' : ('ほか ' + (ch.length - 6) + '件')) + '</div>';
    box.innerHTML = html;
  }).catch(function() { box.innerHTML = '<div class="ck-empty">前月データの読み込みに失敗しました</div>'; });
}
