function gameGreeting() {
  var h = new Date().getHours();
  if (h < 5) return 'おつかれさま';
  if (h < 11) return 'おはようございます';
  if (h < 18) return 'こんにちは';
  return 'こんばんは';
}
function gameDateLabel() {
  var d = new Date(), wd = ['日','月','火','水','木','金','土'][d.getDay()];
  return (d.getMonth()+1) + '月' + d.getDate() + '日(' + wd + ')';
}
function renderHome() {
  var wrap = document.getElementById('view-home');
  if (!wrap) return;
  if (typeof isPCMode === 'function' && !isPCMode()) { _tdyRender(); return; } // v618: スマホの今日＝タイル
  var g = getGame(), today = gameToday();
  if (g.todayMissions.date !== today) g.todayMissions = { date: today, done: [] };
  gameAward(false); // ログイン等を静かに採点
  g = getGame();
  // ※ ミッション/バッジ/週間XPカードの詳細は実績シート（openTrophySheet）でのみ描画。
  //    ホーム毎描画での全メンバー走査（missionDefs/badgeDefs）は行わない＝軽量化。
  var li = gameLevelInfo(g.xp);
  var pct = li.max ? 100 : Math.round(li.into / li.need * 100);
  var name = (currentUser && currentUser.name) ? currentUser.name : '';
  var streak = gameDisplayStreak(g);
  var thisW = g.weekXp || 0, lastW = g.lastWeekXp || 0, dw = thisW - lastW;
  var deltaCls = dw > 0 ? 'up' : (dw < 0 ? 'dn' : 'eq');
  // FTUE（Phase G）：最初の5分チェックリスト。完了までホーム最上部に表示
  var ftueHtml = '';
  try {
    if (!g.ftueDone) {
      var _mAll = (state.members || []).filter(function(m){ return !m.deleted; });
      var _hasRoot = _mAll.some(function(m){ return !m.parentId; });
      var _p3 = state.goals && state.goals.plan && state.goals.plan.title;
      var steps = [
        { ok: _hasRoot, label: '自分をマップに置く', act: "switchView('current')" },
        { ok: _mAll.length >= 4, label: 'メンバーを3人追加する（' + Math.max(0, Math.min(3, _mAll.length - 1)) + '/3）', act: "switchView('current')" },
        { ok: !!_p3, label: '頂上（目標）を決める', act: "switchView('goals');setTimeout(function(){if(typeof glEditGoal==='function')glEditGoal()},300)" },
        { ok: !!(g.gameDays && g.gameDays[today]), label: '今日1つ記録する（クイック記録でOK）', act: "var q=document.querySelector('.qr-grid');if(q)q.scrollIntoView({behavior:'smooth',block:'center'})" }
      ];
      var doneN = steps.filter(function(s){ return s.ok; }).length;
      if (doneN === steps.length) {
        g.ftueDone = 1; saveGame();
        if (g.ftueShown) { gameConfetti(); toast('🎉 セットアップ完了！ここから毎日3分ではじめよう'); }
      } else {
        g.ftueShown = 1;
        ftueHtml = '<div class="home-ftue"><div class="hf-hd">🚀 はじめの4ステップ <span>' + doneN + '/4</span></div>'
          + steps.map(function(s){
              return '<div class="hf-row' + (s.ok ? ' ok' : '') + '"' + (!s.ok && s.act ? ' onclick="' + s.act + '"' : '') + '>'
                + '<span class="hf-ck">' + (s.ok ? '✅' : '⬜') + '</span><span class="hf-lb">' + s.label + '</span>'
                + (!s.ok && s.act ? '<span class="hf-go">›</span>' : '') + '</div>';
            }).join('')
          + '</div>';
      }
    }
  } catch(e) {}
  // おかえりカード（7日以上離脱・大きいストリークが残っている）
  var comebackHtml = '';
  if (streak === 0 && (g.streak || 0) >= 7 && !g.gameDays[today]) {
    comebackHtml = '<div class="home-comeback">🌅 <b>おかえりなさい！</b><br>今日1つ記録すれば、ストリーク<b>' + Math.max(1, Math.floor(g.streak / 2)) + '日</b>から再開できます</div>';
  }
  // v373: クイック記録カードは廃止（quickRecord自体は他画面から利用可能なまま残す）
  // 夜の締めは「今日のルーチン」カードの行に一本化（重複カードを廃止）
  // 自動コーチング（Phase H）：データから「次の一手」を1行だけ提案
  function buildCoachLine() {
    try {
      var p = state.goals && state.goals.plan;
      var curM = (state.members || []).filter(function(m){ return !m.deleted; });
      var dorm = 0; curM.forEach(function(m){ if (memberActivityLevel(m) === 'act-dormant') dorm++; });
      if (dorm >= 3) return '💤 フォロー待ちが' + dorm + '人。今日は新規より「フォローDay」がおすすめ。';
      if (p && p.title && p.funnel) {
        var ym = _glCurYm(), _cF = (typeof _p2FrontTgt === 'function') ? _p2FrontTgt(ym) : '', mF = _cF !== '' ? _cF : _glMonthlyFront(p); // v548: PLANの月のフロント目標
        var _cA = (typeof _p2Act === 'function') ? _p2Act(ym) : null, _cC = (typeof _p2Coef === 'function') ? _p2Coef() : null;
        var d = new Date(), dim = new Date(d.getFullYear(), d.getMonth()+1, 0).getDate(), prog = d.getDate() / dim;
        var actT = mF * (p.funnel.action || 0), actA = _glMonthActual(p, ym, 'action');
        if (actT > 0 && prog > 0.15 && actA < actT * prog * 0.5) return '📣 アクションが目標ペースの半分以下。まず声かけの母数を増やそう。';
        var ctgA = _glMonthActual(p, ym, 'ctget'), ctA = _cA ? _cA.ct : _glMonthActual(p, ym, 'ct');
        if (ctgA >= 4 && ctA < ctgA * 0.4) return '☕ アポ取り→実施の転換が低め。日程は取ったその場で確定しよう。';
        var ftA = _cA ? _cA.ft : _glMonthActual(p, ym, 'ft'), b1A = _cA ? _cA.front : _glMonthActual(p, ym, 'b1');
        if (mF > 0 && ftA >= mF * (_cC ? _cC.ft : (p.funnel.ft || 0)) * 0.7 && b1A === 0 && prog > 0.5) return 'FTは十分打てている。研修動員→B1の「決め」に進もう。';
        if (mF > 0 && b1A >= mF) return '🏆 今月のフロント目標は達成！育成と来月の仕込みに時間を使おう。';
        if (mF > 0) return '今月フロント ' + b1A + '/' + mF + '。逆算どおりに進行中。';
      }
      return '';
    } catch(e) { return ''; }
  }
  var coachLine = buildCoachLine();
  var coachHtml = coachLine ? '<div class="home-coach">' + coachLine + '</div>' : '';
  // 週次成長レポート（Phase E：週が変わったら先週スナップショットと比較）
  var wkHtml = '';
  try {
    var wkNow = gameWeekStart();
    var curMembers = (state.members || []).filter(function(m){ return !m.deleted; });
    var rootM = curMembers.filter(function(m){ return !m.parentId; })[0];
    var curStat = { date: wkNow, n: curMembers.length, gsv: rootM ? (rootM.ptCurrent || 0) : 0 };
    if (!g.wkSnap) { g.wkSnap = curStat; saveGame(); }
    else if (g.wkSnap.date !== wkNow) { g.wkPrev = g.wkSnap; g.wkSnap = curStat; saveGame(); }
    if (g.wkPrev && curMembers.length) {
      var dn = curStat.n - (g.wkPrev.n || 0), dg = curStat.gsv - (g.wkPrev.gsv || 0);
      var dorm = 0; curMembers.forEach(function(m){ if (memberActivityLevel(m) === 'act-dormant') dorm++; });
      wkHtml = '<div class="home-wk">' + icn('sprout') + ' <b>先週からの組織</b>　メンバー ' + (dn >= 0 ? '+' : '') + dn + '人 ・ GSV ' + (dg >= 0 ? '+' : '') + dg.toLocaleString()
        + (dorm ? ' ・ <span style="color:var(--go-rose)">💤フォロー要 ' + dorm + '人</span>' : ' ・ 全員稼働中🔥') + '</div>';
    }
  } catch(e) {}
  // ゲームストリップ（1行）：タップで実績シート（バッジ・ランキングTOP10）
  var dwTxt = dw > 0 ? ('▲+' + dw) : (dw < 0 ? ('▼' + dw) : '±0');
  var stripHtml = '<div class="game-strip" onclick="openTrophySheet()">'
    + '<span class="gs-fire">🔥<b>' + streak + '</b>日</span>'
    + '<span class="gs-lv">Lv.' + li.level + '<span class="gs-bar"><i style="width:' + pct + '%"></i></span></span>'
    + '<span class="gs-wk go-tnum">今週 +' + thisW + 'XP <small class="' + deltaCls + '">' + dwTxt + '</small></span>'
    + '<span class="gs-more">🏅 ›</span></div>';
  wrap.innerHTML = '<div class="home-wrap">'
    + '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px">'
    +   '<div><div class="home-greet">' + gameGreeting() + (name ? ('、' + evEsc(name) + 'さん') : '') + '</div>'
    +   '<div class="home-date">' + gameDateLabel() + '</div></div>'
    +   '<span class="home-bell" onclick="openReleaseNotes()" title="お知らせ（アップデート情報）">' + icn('bell') + (hasUnseenNotes() ? '<i class="bell-dot"></i>' : '') + '</span>'
    + '</div>'
    // v373: 「今日のルーチン」「クイック記録」は実務に合わないため廃止（記録はOL・テンプレ完了・今日の一歩から）
    + ftueHtml
    + comebackHtml
    + stripHtml
    + birthdayHtml()
    + (typeof p2TodayHtml === 'function' ? p2TodayHtml() : '') // v553: 今日の3つ（気になるメンバーより上に）
    + (typeof _p2DoHomeHtml === 'function' ? _p2DoHomeHtml() : '') // v553: 週の作戦 → v580: 今週やること（短い版）
    + cockpitHtml()
    + homeTasksHtml()
    // v374: HOMEの「📁メニュー」カードは☰メニュータブと重複のため廃止
    // 助言系（コーチ・週次・気づき・先月比）は1つの「インサイト」に統合（カード乱立を解消）
    + '<details class="home-insights" style="margin-top:14px"'+(coachHtml?' open':'')+'><summary style="cursor:pointer;font-size:12.5px;font-weight:800;color:var(--text-mid);padding:10px 2px;list-style-position:inside">📈 インサイト（コーチ・今週・先月からの変化）</summary>'
    + coachHtml
    + wkHtml
    + insightsHtml()
    + '<div class="home-sec-label"><span>' + icn('chart') + ' 先月からの変化</span><span onclick="_mcPrevCache={key:\'\',members:null};renderMonthlyChanges()" style="color:var(--text-dim);font-weight:700;font-size:11px;cursor:pointer;padding:4px 10px">↻ 更新</span></div>'
    + '<div id="homeChanges" class="home-changes"><div class="ck-empty" style="color:var(--text-dim)">読み込み中…</div></div>'
    + '</details>'
    + '</div>';
  updateHomeBadge();
  renderMonthlyChanges();
}
// 演出
function gameXpFloat(xp) {
  var el = document.createElement('div'); el.className = 'xp-float'; el.textContent = '+' + xp + ' XP';
  document.body.appendChild(el);
  setTimeout(function(){ if (el.parentNode) el.parentNode.removeChild(el); }, 1100);
}
function gameConfetti() {
  var colors = ['#2CE5B8','#8B7CFF','#FFB454','#FF5D73','#5AD7FF','#FF87B3'];
  for (var i = 0; i < 60; i++) {
    (function(i){
      var c = document.createElement('div'); c.className = 'confetti-pc';
      c.style.left = (Math.random()*100) + 'vw';
      c.style.background = colors[i % colors.length];
      c.style.animationDuration = (1.5 + Math.random()*1.5) + 's';
      c.style.animationDelay = (Math.random()*0.3) + 's';
      document.body.appendChild(c);
      setTimeout(function(){ if (c.parentNode) c.parentNode.removeChild(c); }, 3600);
    })(i);
  }
}
function gameLevelUp(level) {
  gameConfetti();
  if (navigator.vibrate) try { navigator.vibrate([30,40,30]); } catch(e){}
  var b = document.createElement('div'); b.className = 'levelup-banner';
  b.innerHTML = '<div class="levelup-card"><div style="font-size:13px;color:var(--text-dim);letter-spacing:2px">LEVEL UP</div>'
    + '<div style="font-size:42px;font-weight:800;color:var(--accent);font-family:Inter,IBM Plex Mono,monospace;margin:4px 0">Lv.' + level + '</div>'
    + '<div style="font-size:14px">おめでとう！🎉</div></div>';
  document.body.appendChild(b);
  setTimeout(function(){ if (b.parentNode) b.parentNode.removeChild(b); }, 1900);
}

// ── PC ビュー切替 ──
var _pcView = 'tree'; // 'tree' | 'table' | 'kanban'
function switchPCView(view) {
  _pcView = view;
  // ボタン状態
  var ids = ['pvTree','pvTable','pvKanban','pvTreeI','pvTableI','pvOrbit','pvOrbitI'];
  ids.forEach(function(id) {
    var el = document.getElementById(id);
    if (!el) return;
    var match = (id.indexOf('Tree') >= 0 && view === 'tree')
      || (id.indexOf('Table') >= 0 && view === 'table')
      || (id.indexOf('Kanban') >= 0 && view === 'kanban')
      || (id.indexOf('Orbit') >= 0 && view === 'orbit');
    el.classList.toggle('active', match);
  });
  // 表示切替
  var treeC = document.getElementById('pcMapCurrent');
  var treeI = document.getElementById('pcMapIdeal');
  var tblC = document.getElementById('pcTableCurrent');
  var tblI = document.getElementById('pcTableIdeal');
  var fltC = document.getElementById('pcFilterCurrent');
  var fltI = document.getElementById('pcFilterIdeal');
  var kbnC = document.getElementById('pcKanbanCurrent');
  var orbC = document.getElementById('pcOrbitCurrent');
  var orbI = document.getElementById('pcOrbitIdeal');
  if (treeC) treeC.style.display = view === 'tree' ? '' : 'none';
  if (treeI) treeI.style.display = view === 'tree' ? '' : 'none';
  if (tblC) tblC.classList.toggle('show', view === 'table');
  if (tblI) tblI.classList.toggle('show', view === 'table');
  if (fltC) fltC.classList.toggle('show', view === 'table');
  if (fltI) fltI.classList.toggle('show', view === 'table');
  var catC = document.getElementById('pcMapCatChips'); // v471: カテゴリ絞り込みはツリー/俯瞰表示のみ
  if (catC) catC.classList.toggle('show', view === 'tree' || view === 'orbit');
  if (kbnC) kbnC.classList.toggle('show', view === 'kanban');
  if (orbC) orbC.classList.toggle('show', view === 'orbit');
  if (orbI) orbI.classList.toggle('show', view === 'orbit');
  if (view === 'table') {
    if (currentView === 'current') renderPCTable('current');
    else if (currentView === 'ideal') renderPCTable('ideal');
  }
  if (view === 'kanban') renderKanban();
  if (view === 'orbit') {
    if (currentView === 'ideal') renderPCOrbit('ideal');
    else renderPCOrbit('current');
  }
  if (view === 'tree') renderCurrentView(); // 俯瞰中に更新された分を再構築
}

// ── PC テーブルビュー ──
var _tblSort = { col: 'depth', asc: true };
var _tblFilterDepth = null;
var _tblFilterAct = '';

function renderPCTable(mapType) {
  var containerId = mapType === 'current' ? 'pcTableCurrent' : 'pcTableIdeal';
  var filterId = mapType === 'current' ? 'pcFilterCurrent' : 'pcFilterIdeal';
  var wrap = document.getElementById(containerId);
  var filterWrap = document.getElementById(filterId);
  if (!wrap) return;
  wrap.innerHTML = '';
  if (filterWrap) filterWrap.innerHTML = '';

  var members = membersForMap(mapType);
  if (!members || members.length === 0) {
    wrap.innerHTML = '<div style="padding:40px;text-align:center;color:var(--text-dim)">メンバーなし</div>';
    return;
  }

  // 各メンバーの深さ・系列カラーを計算
  var COLORS = ['#2CE5B8','#8B7CFF','#FFB454','#FF5D73','#5AD7FF','#4ADE80','#FF9F6E','#C583FF'];
  var depthMap = {};
  var familyMap = {};
  var roots = members.filter(function(m) { return !m.parentId; });

  function calcDepth(id, d) {
    depthMap[id] = d;
    members.filter(function(m) { return m.parentId === id; }).forEach(function(m) { calcDepth(m.id, d + 1); });
  }
  roots.forEach(function(r) { calcDepth(r.id, 0); });

  // 系列カラー
  roots.forEach(function(r) {
    familyMap[r.id] = COLORS[0];
    var fKids = members.filter(function(m) { return m.parentId === r.id; });
    fKids.forEach(function(kid, fi) {
      var col = COLORS[(fi + 1) % COLORS.length];
      function setColor(id, c) {
        familyMap[id] = c;
        members.filter(function(m) { return m.parentId === id; }).forEach(function(m) { setColor(m.id, c); });
      }
      setColor(kid.id, col);
    });
  });

  // ツリー順でフラット配列にする
  var flatList = [];
  function walkTree(id) {
    var m = null;
    for (var i = 0; i < members.length; i++) { if (members[i].id === id) { m = members[i]; break; } }
    if (!m) return;
    flatList.push(m);
    members.filter(function(c) { return c.parentId === id; }).forEach(function(c) { walkTree(c.id); });
  }
  roots.forEach(function(r) { walkTree(r.id); });

  // フィルタ
  var filtered = flatList.filter(function(m) {
    if (_tblFilterDepth !== null && depthMap[m.id] !== _tblFilterDepth) return false;
    if (_tblFilterAct && m.activity !== _tblFilterAct) return false;
    return true;
  });

  // ソート
  if (_tblSort.col !== 'tree') {
    filtered.sort(function(a, b) {
      var va, vb;
      switch (_tblSort.col) {
        case 'depth': va = depthMap[a.id]||0; vb = depthMap[b.id]||0; break;
        case 'name': va = (a.lastName||'')+(a.firstName||''); vb = (b.lastName||'')+(b.firstName||''); break;
        case 'title': va = a.title||''; vb = b.title||''; break;
        case 'activity': va = a.activity||'Z'; vb = b.activity||'Z'; break;
        case 'gsv': va = a.ptCurrent||0; vb = b.ptCurrent||0; break;
        case 'fixed': va = a.ptFixed||0; vb = b.ptFixed||0; break;
        case 'morale': va = a.morale||0; vb = b.morale||0; break;
        default: va = depthMap[a.id]||0; vb = depthMap[b.id]||0;
      }
      if (typeof va === 'string') return _tblSort.asc ? va.localeCompare(vb) : vb.localeCompare(va);
      return _tblSort.asc ? va - vb : vb - va;
    });
  }

  // フィルターバー
  var filterBar = document.createElement('div');
  filterBar.className = 'tbl-filter-bar';

  // 段数フィルター
  var maxDepth = 0;
  flatList.forEach(function(m) { if ((depthMap[m.id]||0) > maxDepth) maxDepth = depthMap[m.id]; });
  var allChip = document.createElement('div');
  allChip.className = 'tbl-filter-chip' + (_tblFilterDepth === null ? ' active' : '');
  allChip.textContent = '全段 ' + flatList.length;
  allChip.onclick = function() { _tblFilterDepth = null; renderPCTable(mapType); };
  filterBar.appendChild(allChip);
  for (var d = 0; d <= maxDepth; d++) {
    (function(dd) {
      var cnt = flatList.filter(function(m) { return depthMap[m.id] === dd; }).length;
      if (cnt === 0) return;
      var chip = document.createElement('div');
      chip.className = 'tbl-filter-chip' + (_tblFilterDepth === dd ? ' active' : '');
      chip.textContent = dd + '段 ' + cnt;
      chip.onclick = function() { _tblFilterDepth = dd; renderPCTable(mapType); };
      filterBar.appendChild(chip);
    })(d);
  }

  // 稼働フィルター
  var sep = document.createElement('span');
  sep.style.cssText = 'width:1px;height:16px;background:var(--border);margin:0 4px';
  filterBar.appendChild(sep);
  ['S','A','B','C'].forEach(function(act) {
    var cnt = flatList.filter(function(m) { return m.activity === act; }).length;
    if (cnt === 0) return;
    var chip = document.createElement('div');
    chip.className = 'tbl-filter-chip' + (_tblFilterAct === act ? ' active' : '');
    chip.style.color = act==='S'?'var(--s)':act==='A'?'var(--a)':act==='B'?'var(--b)':'var(--c)';
    if (_tblFilterAct === act) chip.style.borderColor = chip.style.color;
    chip.textContent = act + ' ' + cnt;
    chip.onclick = function() { _tblFilterAct = _tblFilterAct === act ? '' : act; renderPCTable(mapType); };
    filterBar.appendChild(chip);
  });

  if (filterWrap) filterWrap.appendChild(filterBar);
  else wrap.appendChild(filterBar);

  // テーブル
  var table = document.createElement('table');
  table.className = 'org-table';

  var cols = [
    { key: 'tree', label: '' , w: '6px' },
    { key: 'depth', label: '段' },
    { key: 'actions', label: '', nosort: true },
    { key: 'name', label: '名前' },
    { key: 'title', label: 'タイトル' },
    { key: 'activity', label: '稼働' },
    { key: 'gsv', label: 'GSV' },
    { key: 'fixed', label: '固定PT' },
    { key: 'morale', label: '' },
    { key: 'trainee', label: '研修' },
    { key: 'memo', label: 'メモ' }
  ];

  // ヘッダー
  var thead = document.createElement('thead');
  var hrow = document.createElement('tr');
  cols.forEach(function(c) {
    var th = document.createElement('th');
    if (c.key === 'tree') { th.style.width = c.w; th.style.padding = '0'; }
    else if (c.key === 'actions') { th.style.width = '60px'; th.style.padding = '0'; }
    else if (c.nosort) { th.textContent = c.label; }
    else {
      th.textContent = c.label;
      var arrow = document.createElement('span');
      arrow.className = 'sort-arrow';
      arrow.textContent = _tblSort.col === c.key ? (_tblSort.asc ? '▲' : '▼') : '▲';
      th.appendChild(arrow);
      if (_tblSort.col === c.key) th.className = 'sorted';
      th.onclick = function() {
        if (_tblSort.col === c.key) _tblSort.asc = !_tblSort.asc;
        else { _tblSort.col = c.key; _tblSort.asc = true; }
        renderPCTable(mapType);
      };
    }
    hrow.appendChild(th);
  });
  thead.appendChild(hrow);
  table.appendChild(thead);

  // ボディ
  var tbody = document.createElement('tbody');
  var isEd = state.isEditor;
  filtered.forEach(function(m) {
    var tr = document.createElement('tr');
    tr.dataset.mid = m.id;

    // 系列カラー
    var tdF = document.createElement('td');
    tdF.className = 'col-family';
    var dot = document.createElement('div');
    dot.className = 'col-family-dot';
    dot.style.background = familyMap[m.id] || '#444';
    tdF.appendChild(dot);
    tr.appendChild(tdF);

    // 段
    var tdD = document.createElement('td');
    tdD.className = 'col-depth';
    tdD.textContent = depthMap[m.id] !== undefined ? depthMap[m.id] : '-';
    tdD.style.color = familyMap[m.id] || 'var(--text-dim)';
    tr.appendChild(tdD);

    // アクション列（名前の左）
    var tdAc = document.createElement('td');
    tdAc.className = 'col-actions';
    if (isEd) {
      var addBtn = document.createElement('button');
      addBtn.className = 'tbl-act-btn add';
      addBtn.textContent = '+';
      addBtn.title = 'この人の直下に追加';
      (function(parentId) {
        addBtn.onclick = function(e) { e.stopPropagation(); tblAddChild(parentId, mapType); };
      })(m.id);
      tdAc.appendChild(addBtn);
      var delBtn = document.createElement('button');
      delBtn.className = 'tbl-act-btn del';
      delBtn.textContent = '×';
      delBtn.title = '削除';
      (function(mid, mName) {
        delBtn.onclick = function(e) { e.stopPropagation(); tblDeleteMember(mid, mName, mapType); };
      })(m.id, (m.lastName||'')+(m.firstName||''));
      tdAc.appendChild(delBtn);
    }
    tr.appendChild(tdAc);

    // 名前（クリックで姓・名を編集）
    var tdN = document.createElement('td');
    tdN.className = 'col-name ' + (m.gender || 'male') + (isEd ? ' editable' : '');
    tdN.textContent = (m.lastName || '') + ' ' + (m.firstName || '');
    if (isEd) tdN.onclick = function() { inlineText(tdN, m, 'name', mapType); };
    tr.appendChild(tdN);

    // タイトル（ドロップダウン）
    var tdT = document.createElement('td');
    tdT.className = 'col-title' + (isEd ? ' editable' : '');
    var LOI_T = ['LOI','Q2','Q3','Q4'];
    if (LOI_T.indexOf((m.title||'').trim()) >= 0) tdT.style.color = '#4ADE80';
    else if (m.trainee) tdT.style.color = '#5AD7FF';
    tdT.textContent = m.title || '-';
    if (isEd) tdT.onclick = function() { inlineSelect(tdT, m, 'title', mapType); };
    tr.appendChild(tdT);

    // 稼働（ドロップダウン）
    var tdA = document.createElement('td');
    tdA.className = 'col-act' + (isEd ? ' editable' : '');
    var actText = m.activity || '-';
    if (m.activity && m.actRate) actText += ' ' + m.actRate + '%';
    if (m.activity === 'S' && !m.actRate) actText = 'S 120%'; // v492: 実測があればそちら
    tdA.textContent = actText;
    tdA.style.color = m.activity==='S'?'var(--s)':m.activity==='A'?'var(--a)':m.activity==='B'?'var(--b)':m.activity==='C'?'var(--c)':'var(--text-dim)';
    if (isEd) tdA.onclick = function() { inlineSelect(tdA, m, 'activity', mapType); };
    tr.appendChild(tdA);

    // GSV
    var tdG = document.createElement('td');
    tdG.className = 'col-gsv editable';
    tdG.textContent = m.ptCurrent > 0 ? m.ptCurrent.toLocaleString() : '-';
    if (isEd) tdG.onclick = function() { inlineNum(tdG, m, 'ptCurrent', mapType); };
    tr.appendChild(tdG);

    // 固定PT
    var tdFx = document.createElement('td');
    tdFx.className = 'col-fixed editable';
    tdFx.textContent = m.ptFixed > 0 ? m.ptFixed.toLocaleString() : '-';
    if (isEd) tdFx.onclick = function() { inlineNum(tdFx, m, 'ptFixed', mapType); };
    tr.appendChild(tdFx);

    // やる気（ドロップダウン）
    var tdM = document.createElement('td');
    tdM.className = 'col-morale' + (isEd ? ' editable' : '');
    tdM.innerHTML = moraleIcon(m.morale||1);
    if (isEd) tdM.onclick = function() { inlineSelect(tdM, m, 'morale', mapType); };
    tr.appendChild(tdM);

    // 研修
    var tdTr = document.createElement('td');
    tdTr.className = 'col-trainee';
    if (m.traineeResult) {
      tdTr.textContent = m.traineeResult;
      tdTr.style.color = m.traineeResult === 'BC' ? 'var(--accent)' : m.traineeResult === '流れた' ? 'var(--red)' : 'var(--gold)';
    } else if (m.trainee) {
      var ls = getLatestStatus(m);
      tdTr.textContent = ls || '研修中';
      tdTr.style.color = '#5AD7FF';
    }
    tr.appendChild(tdTr);

    // メモ（テキストエリア）
    var tdMe = document.createElement('td');
    tdMe.className = 'col-memo' + (isEd ? ' editable' : '');
    tdMe.textContent = m.memo || '';
    tdMe.title = m.memo || '';
    if (isEd) tdMe.onclick = function() { inlineMemo(tdMe, m, mapType); };
    tr.appendChild(tdMe);

    tbody.appendChild(tr);
  });

  // 追加行（テーブル末尾）
  if (isEd) {
    var addTr = document.createElement('tr');
    addTr.className = 'tbl-add-row';
    var addTd = document.createElement('td');
    addTd.colSpan = cols.length;
    addTd.textContent = '＋ メンバーを追加';
    addTd.onclick = function() { tblAddChild('', mapType); };
    addTr.appendChild(addTd);
    tbody.appendChild(addTr);
  }

  table.appendChild(tbody);
  wrap.appendChild(table);
}

// テーブルから直接メンバー追加（インラインで新行挿入）
function tblAddChild(parentId, mapType) {
  var newId = 'id-' + Date.now();
  var newMember = {
    id: newId,
    parentId: parentId,
    lastName: '',
    firstName: '',
    gender: 'male',
    title: '',
    activity: '',
    actRate: '',
    morale: 1,
    ptCurrent: 0,
    ptSelf: 0,
    ptFixed: 0,
    trainee: false,
    traineeHistory: [],
    traineeResult: '',
    mapType: currentView === 'ideal' ? 'ideal' : 'current',
    memo: '',
    month: state.currentMonth
  };
  state.members.push(newMember);
  autoSave();
  renderPCTable(mapType);
  // 新しい行にスクロール＆名前セルをクリック
  setTimeout(function() {
    var wrap = document.getElementById(mapType === 'current' ? 'pcTableCurrent' : 'pcTableIdeal');
    if (!wrap) return;
    var rows = wrap.querySelectorAll('tr[data-mid="' + newId + '"]');
    if (rows.length > 0) {
      rows[0].scrollIntoView({ block: 'center' });
      var nameCell = rows[0].querySelector('.col-name');
      if (nameCell && nameCell.onclick) nameCell.onclick();
    }
  }, 100);
}

// テーブルから直接メンバー削除（ソフトデリート）
function tblDeleteMember(mid, name, mapType) {
  if (!confirm((name || 'このメンバー') + ' を削除しますか？')) return;
  var delParent = '';
  for (var i = 0; i < state.members.length; i++) {
    if (state.members[i].id === mid) {
      state.members[i].deleted = true;
      delParent = state.members[i].parentId || '';
      break;
    }
  }
  // 子を親に付け替え
  for (var j = 0; j < state.members.length; j++) {
    if (state.members[j].parentId === mid) {
      state.members[j].parentId = delParent;
    }
  }
  autoSave();
  renderPCTable(mapType);
  renderCurrentView();
}

// ── テーブル インライン編集 ──
function inlineNum(td, member, field, mapType) {
  if (td.querySelector('input')) return;
  var oldVal = member[field] || 0;
  var input = document.createElement('input');
  input.className = 'inline-input';
  input.type = 'number';
  input.value = oldVal;
  td.textContent = '';
  td.appendChild(input);
  input.focus(); input.select();
  function finish() {
    var v = parseInt(input.value) || 0;
    if (field === 'ptCurrent') {
      // GSV手入力 → 自分の分(ptSelf)に変換し、全体再計算でアップラインへ反映
      var arr = (mapType === 'ideal') ? state.idealMembers : state.members;
      setMemberGSV(member, v, arr);
      autoSave();
      renderCurrentView(); // アップラインのGSVも再描画
      return;
    }
    member[field] = v;
    td.textContent = v > 0 ? v.toLocaleString() : '-';
    autoSave();
  }
  input.onblur = finish;
  input.onkeydown = function(e) { if (e.key === 'Enter') input.blur(); else if (e.key === 'Escape') { member[field] = oldVal; renderPCTable(mapType); } };
}

function inlineText(td, member, field, mapType) {
  if (td.querySelector('input')) return;
  var oldLast = member.lastName || '';
  var oldFirst = member.firstName || '';
  td.textContent = '';
  var i1 = document.createElement('input'); i1.className = 'inline-input'; i1.style.width = '60px'; i1.placeholder = '姓'; i1.value = oldLast;
  var i2 = document.createElement('input'); i2.className = 'inline-input'; i2.style.width = '60px'; i2.style.marginLeft = '4px'; i2.placeholder = '名'; i2.value = oldFirst;
  td.appendChild(i1); td.appendChild(i2);
  i1.focus();
  function finish() {
    member.lastName = i1.value.trim(); member.firstName = i2.value.trim();
    td.textContent = (member.lastName || '') + ' ' + (member.firstName || '');
    autoSave();
  }
  i1.onblur = function() { setTimeout(function() { if (document.activeElement !== i2) finish(); }, 100); };
  i2.onblur = finish;
  i2.onkeydown = function(e) { if (e.key === 'Enter') i2.blur(); };
  i1.onkeydown = function(e) { if (e.key === 'Enter') i2.focus(); };
}

function inlineSelect(td, member, field, mapType) {
  if (td.querySelector('select')) return;
  var sel = document.createElement('select');
  sel.className = 'inline-select';
  var options = [];
  if (field === 'title') {
    options = ['-'];
    var allTitles = (TITLE_OPTIONS['研修生']||[]).concat(TITLE_OPTIONS['BA']||[]).concat(TITLE_OPTIONS['BR']||[]);
    allTitles.forEach(function(t) { options.push(t); });
  } else if (field === 'activity') {
    options = ['-','S','A','B','C'];
  } else if (field === 'morale') {
    options = [{v:'1',l:'🌱'},{v:'2',l:'💪'},{v:'3',l:'🔥'}];
  }
  if (field === 'morale') {
    options.forEach(function(o) {
      var opt = document.createElement('option'); opt.value = o.v; opt.textContent = o.l;
      if (parseInt(o.v) === (member.morale||1)) opt.selected = true;
      sel.appendChild(opt);
    });
  } else {
    options.forEach(function(o) {
      var opt = document.createElement('option'); opt.value = o === '-' ? '' : o; opt.textContent = o;
      if ((field === 'title' && (member.title||'') === (o==='-'?'':o)) || (field === 'activity' && (member.activity||'') === (o==='-'?'':o))) opt.selected = true;
      sel.appendChild(opt);
    });
  }
  td.textContent = '';
  td.appendChild(sel);
  sel.focus();
  function finish() {
    if (field === 'morale') {
      member.morale = parseInt(sel.value) || 1;
      td.innerHTML = moraleIcon(member.morale);
    } else if (field === 'activity') {
      member.activity = sel.value;
      td.style.color = member.activity==='S'?'var(--s)':member.activity==='A'?'var(--a)':member.activity==='B'?'var(--b)':member.activity==='C'?'var(--c)':'var(--text-dim)';
      // S以外は%入力を表示
      if (member.activity && member.activity !== 'S') {
        if (sel.parentNode) sel.parentNode.removeChild(sel);
        var pctInput = document.createElement('input');
        pctInput.className = 'inline-input';
        pctInput.type = 'number';
        pctInput.style.width = '60px';
        pctInput.placeholder = '%';
        pctInput.value = member.actRate || '';
        td.textContent = '';
        var label = document.createElement('span');
        label.textContent = member.activity + ' ';
        label.style.cssText = 'font-weight:600;margin-right:4px;color:' + td.style.color;
        td.appendChild(label);
        td.appendChild(pctInput);
        pctInput.focus();
        pctInput.onblur = function() {
          member.actRate = pctInput.value.trim();
          var actText2 = member.activity + (member.actRate ? ' ' + member.actRate + '%' : '');
          td.textContent = actText2;
          autoSave();
        };
        pctInput.onkeydown = function(e) { if (e.key === 'Enter') pctInput.blur(); };
        return;
      }
      var actText = member.activity || '-';
      if (member.activity === 'S' && !member.actRate) actText = 'S 120%'; // v492
      td.textContent = actText;
    } else {
      member[field] = sel.value;
      td.textContent = sel.value || '-';
    }
    autoSave();
  }
  sel.onchange = function() { finish(); };
  sel.onblur = function() { finish(); };
}

function inlineMemo(td, member, mapType) {
  if (td.querySelector('textarea')) return;
  var ta = document.createElement('textarea');
  ta.className = 'inline-textarea';
  ta.value = member.memo || '';
  td.textContent = '';
  td.appendChild(ta);
  ta.focus();
  function finish() {
    member.memo = ta.value.trim();
    td.textContent = member.memo || '';
    td.title = member.memo || '';
    autoSave();
  }
  ta.onblur = finish;
  ta.onkeydown = function(e) { if (e.key === 'Escape') { member.memo = ta.value.trim(); renderPCTable(mapType); } };
}

// ── ミニマップ ──
function renderMinimap(outerWrap, outer, svg, SVG_W, SVG_H, viewW, viewH, zoom, posMap, members, cmap) {
  var mm = document.createElement('div');
  mm.className = 'minimap';
  var canvas = document.createElement('canvas');
  canvas.width = 180; canvas.height = 120;
  mm.appendChild(canvas);
  var vp = document.createElement('div');
  vp.className = 'minimap-viewport';
  mm.appendChild(vp);
  outerWrap.appendChild(mm);

  function draw() {
    var ctx = canvas.getContext('2d');
    var scaleX = 180 / SVG_W;
    var scaleY = 120 / SVG_H;
    var sc = Math.min(scaleX, scaleY);
    ctx.clearRect(0, 0, 180, 120);

    // ノードを描画
    members.forEach(function(m) {
      var pos = posMap[m.id];
      if (!pos) return;
      var col = cmap[m.id] || '#444';
      ctx.fillStyle = col;
      ctx.globalAlpha = 0.7;
      ctx.fillRect(pos.x * sc - 1.5, pos.y * sc - 1, 3, 2);
    });
    ctx.globalAlpha = 1;

    // 接続線
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 0.5;
    members.forEach(function(m) {
      if (!m.parentId || !posMap[m.id] || !posMap[m.parentId]) return;
      ctx.beginPath();
      ctx.moveTo(posMap[m.parentId].x * sc, posMap[m.parentId].y * sc);
      ctx.lineTo(posMap[m.id].x * sc, posMap[m.id].y * sc);
      ctx.stroke();
    });

    // ビューポート矩形
    var z = parseFloat(outer._currentZoom) || 0.6;
    var vpW = (viewW / z) * sc;
    var vpH = (viewH / z) * sc;
    var vpX = (outer.scrollLeft / z) * sc;
    var vpY = (outer.scrollTop / z) * sc;
    vp.style.left = Math.max(0, vpX) + 'px';
    vp.style.top = Math.max(0, vpY) + 'px';
    vp.style.width = Math.min(vpW, 180) + 'px';
    vp.style.height = Math.min(vpH, 120) + 'px';
  }

  draw();
  outer._currentZoom = zoom;
  outer.addEventListener('scroll', function() { draw(); });

  // ミニマップクリックでスクロール
  mm.addEventListener('click', function(e) {
    var rect = canvas.getBoundingClientRect();
    var mx = e.clientX - rect.left;
    var my = e.clientY - rect.top;
    var sc = Math.min(180 / SVG_W, 120 / SVG_H);
    var z = parseFloat(outer._currentZoom) || 0.6;
    outer.scrollLeft = (mx / sc - viewW / z / 2) * z;
    outer.scrollTop = (my / sc - viewH / z / 2) * z;
  });

  return { draw: draw };
}

// ── カンバンビュー ──
function renderKanban() {
  var wrap = document.getElementById('pcKanbanCurrent');
  if (!wrap) return;
  wrap.innerHTML = '';

  var members = membersForMap('current');
  // 研修経験者を抽出
  var trainees = members.filter(function(m) {
    return !!m.trainee || !!m.traineeResult || (m.traineeHistory && m.traineeHistory.length > 0);
  });

  if (trainees.length === 0) {
    wrap.innerHTML = '<div style="padding:40px;text-align:center;color:var(--text-dim)">研修生がいません</div>';
    return;
  }

  // Aさんでグルーピング切替
  var groupBy = window._kanbanGroup || 'step'; // 'step' | 'asan'
  var toggleBar = document.createElement('div');
  toggleBar.style.cssText = 'display:flex;gap:6px;padding:8px 0;align-items:center';
  var lbl = document.createElement('span');
  lbl.style.cssText = 'font-size:11px;color:var(--text-dim);font-family:Inter,sans-serif';
  lbl.textContent = '表示:';
  toggleBar.appendChild(lbl);
  ['step','asan'].forEach(function(g) {
    var btn = document.createElement('div');
    btn.className = 'tbl-filter-chip' + (groupBy === g ? ' active' : '');
    btn.textContent = g === 'step' ? 'ステップ別' : 'Aさん別';
    btn.onclick = function() { window._kanbanGroup = g; renderKanban(); };
    toggleBar.appendChild(btn);
  });
  // 人数
  var cntEl = document.createElement('span');
  cntEl.style.cssText = 'font-size:11px;color:var(--text-dim);font-family:Inter,sans-serif;margin-left:auto';
  cntEl.textContent = '研修生 ' + trainees.length + '人';
  toggleBar.appendChild(cntEl);
  wrap.appendChild(toggleBar);

  var board = document.createElement('div');
  board.className = 'kanban-board';

  if (groupBy === 'step') {
    renderKanbanByStep(board, trainees);
  } else {
    renderKanbanByAsan(board, trainees);
  }

  wrap.appendChild(board);
}

function renderKanbanByStep(board, trainees) {
  var STEPS = ['マケ','PG','DLR','EXP','PA','面談','BPC','CO']; // v401
  var RESULTS = [
    { key: 'BC', label: 'BC（成約）', color: 'var(--accent)' },
    { key: 'ユーザー', label: 'ユーザー', color: 'var(--gold)' },
    { key: '流れた', label: '流れた', color: 'var(--red)' }
  ];

  // 各ステップに属するメンバーを分類（最新ステップで分類）
  var stepMap = {};
  STEPS.forEach(function(s) { stepMap[s] = []; });
  var resultMap = { 'BC': [], 'ユーザー': [], '流れた': [] };
  var inProgress = [];

  trainees.forEach(function(m) {
    if (m.traineeResult) {
      if (resultMap[m.traineeResult]) resultMap[m.traineeResult].push(m);
      return;
    }
    var latest = getLatestStatus(m);
    if (latest && stepMap[latest]) {
      stepMap[latest].push(m);
    } else {
      inProgress.push(m);
    }
  });

  // 進行中（ステップなし）
  if (inProgress.length > 0) {
    board.appendChild(buildKanbanCol('未着手', inProgress, 'var(--text-dim)'));
  }

  // ステップ列
  STEPS.forEach(function(s) {
    board.appendChild(buildKanbanCol(s, stepMap[s], 'var(--accent)'));
  });

  // 結果列
  RESULTS.forEach(function(r) {
    var col = buildKanbanCol(r.label, resultMap[r.key], r.color);
    col.classList.add('kanban-result-col');
    board.appendChild(col);
  });
}

function renderKanbanByAsan(board, trainees) {
  var asanMap = {};
  var noAsan = [];
  trainees.forEach(function(m) {
    var hist = m.traineeHistory || [];
    var asan = '';
    for (var i = hist.length - 1; i >= 0; i--) {
      if (hist[i].aSan) { asan = hist[i].aSan; break; }
    }
    if (asan) {
      if (!asanMap[asan]) asanMap[asan] = [];
      asanMap[asan].push(m);
    } else {
      noAsan.push(m);
    }
  });

  var keys = Object.keys(asanMap).sort();
  keys.forEach(function(k) {
    board.appendChild(buildKanbanCol(k, asanMap[k], 'var(--purple)'));
  });
  if (noAsan.length > 0) {
    board.appendChild(buildKanbanCol('Aさん未設定', noAsan, 'var(--text-dim)'));
  }
}

function buildKanbanCol(title, members, color) {
  var col = document.createElement('div');
  col.className = 'kanban-col';

  var hdr = document.createElement('div');
  hdr.className = 'kanban-col-hdr';
  hdr.style.color = color;
  var t = document.createElement('span');
  t.textContent = title;
  hdr.appendChild(t);
  var cnt = document.createElement('span');
  cnt.className = 'kanban-col-count';
  cnt.textContent = members.length;
  hdr.appendChild(cnt);
  col.appendChild(hdr);

  var body = document.createElement('div');
  body.className = 'kanban-col-body';

  members.forEach(function(m) {
    var card = document.createElement('div');
    card.className = 'kanban-card';
    card.ondblclick = function() { if (state.isEditor) openEdit(m.id); };

    var name = document.createElement('div');
    name.className = 'kanban-card-name ' + (m.gender || 'male');
    name.textContent = (m.lastName || '') + ' ' + (m.firstName || '');
    card.appendChild(name);

    var sub = document.createElement('div');
    sub.className = 'kanban-card-sub';
    var parts = [];
    if (m.title) parts.push(m.title);
    if (m.traineeResult) {
      var rc = m.traineeResult === 'BC' ? 'var(--accent)' : m.traineeResult === '流れた' ? 'var(--red)' : 'var(--gold)';
      sub.style.color = rc;
      parts.push(m.traineeResult);
    }
    sub.textContent = parts.join(' | ');
    card.appendChild(sub);

    // Aさん表示
    var hist = m.traineeHistory || [];
    var asan = '';
    for (var i = hist.length - 1; i >= 0; i--) {
      if (hist[i].aSan) { asan = hist[i].aSan; break; }
    }
    if (asan) {
      var asEl = document.createElement('div');
      asEl.className = 'kanban-card-asan';
      asEl.textContent = 'A: ' + asan;
      card.appendChild(asEl);
    }

    body.appendChild(card);
  });

  col.appendChild(body);
  return col;
}

// ── TREE ──
