function getTraineeMember() {
  var m = null;
  for (var j=0; j<state.members.length; j++) {
    if (state.members[j].id === editingId) { m = state.members[j]; break; }
  }
  if (!m && !editingId) {
    if (!window._tempNewMember) window._tempNewMember = { id:'__new__', traineeHistory:[], traineeStatus:'' };
    m = window._tempNewMember;
  }
  return m;
}

function renderTraineeHistory(m) {
  var wrap = document.getElementById('traineeHistoryWrap');
  if (!wrap) return;
  var member = getTraineeMember();
  if (!member && m) member = m;
  wrap.innerHTML = '';
  var hist = member ? (member.traineeHistory || []) : [];
  if (hist.length === 0) {
    wrap.innerHTML = '<div style="color:var(--text-dim);font-size:12px;padding:8px 0;text-align:center">まだ記録なし</div>';
    updateStepFlow(hist);
    return;
  }
  // タイムライン表示
  var timeline = document.createElement('div');
  timeline.className = 'th-timeline';
  // v405: 表示は日付順（入力順ではなく）。削除・確定の操作は元の配列位置(i)で行うため添字を保持して並べ替える
  var _disp = hist.map(function(hh, ii){ return { h: hh, i: ii }; });
  _disp.sort(function(a, b){
    var ka = a.h.date || '9999-99-99', kb = b.h.date || '9999-99-99';
    return ka < kb ? -1 : (ka > kb ? 1 : (a.i - b.i));
  });
  _disp.forEach(function(_it) {
    var h = _it.h, i = _it.i;
    var entry = document.createElement('div');
    var cls = h.result === 'left' ? ' result-left' : (h.result === 'planned' ? ' result-planned' : ' result-bc');
    entry.className = 'th-entry' + cls;
    var stepName = document.createElement('div');
    stepName.className = 'th-step-name';
    if (h.ir) { entry.classList.add('th-ir'); stepName.style.color = 'var(--text-mid)'; } // v401: フォロー記録は控えめに
    stepName.textContent = (h.result === 'planned' ? '📅 ' : '') + (h.ir ? '📝 ' : '') + (h.status || '');
    entry.appendChild(stepName);
    var meta = document.createElement('div');
    meta.className = 'th-meta';
    // v413: リスケ（日程調整中／リスケ回数・元の日付）
    if (h.tbd) {
      var tb = document.createElement('span');
      var _tdD = h.rsAt ? Math.floor((Date.now() - new Date(h.rsAt).getTime()) / 86400000) : 0;
      tb.textContent = '📅 日程調整中' + (_tdD >= 1 ? '（' + _tdD + '日）' : '');
      tb.style.color = _tdD >= 7 ? 'var(--red)' : (_tdD >= 3 ? '#FFB454' : 'var(--text-mid)');
      tb.style.fontWeight = '700';
      meta.appendChild(tb);
      if (h.date) { var ds0 = document.createElement('span'); ds0.textContent = '元 ' + h.date; ds0.style.opacity = '.7'; meta.appendChild(ds0); }
    } else if (h.date) { var ds = document.createElement('span'); ds.textContent = h.date; meta.appendChild(ds); }
    if (h.rs) { var rsB = document.createElement('span'); rsB.textContent = '🔄リスケ' + h.rs + '回'; rsB.style.color = h.rs >= 3 ? 'var(--red)' : 'var(--text-dim)'; meta.appendChild(rsB); }
    if (h.aSan) { var as2 = document.createElement('span'); as2.textContent = 'A: ' + h.aSan; meta.appendChild(as2); }
    if (h.ck) { var ck2 = document.createElement('span'); ck2.textContent = '受付から'; ck2.style.color = 'var(--accent)'; meta.appendChild(ck2); } // v623
    var rs = document.createElement('span');
    rs.textContent = h.result === 'left' ? '✗ 流れた' : (h.result === 'planned' ? (h.tbd ? '📅 調整中' : '📅 予定') : (h.ir ? '✓ 実施' : '✓ 進んだ'));
    rs.style.color = h.result === 'left' ? 'var(--red)' : (h.result === 'planned' ? '#FFB454' : 'var(--accent)');
    meta.appendChild(rs);
    entry.appendChild(meta);
    // 予定エントリ：後から結果を確定
    if (h.result === 'planned') {
      var acts = document.createElement('div');
      acts.className = 'th-acts';
      (function(idx){
        var bN = document.createElement('button'); bN.className = 'th-act-btn go'; bN.textContent = '✓ 進んだ';
        bN.onclick = function(){ setStepResult(idx, 'next'); };
        var bL = document.createElement('button'); bL.className = 'th-act-btn left'; bL.textContent = '✗ 流れた';
        bL.onclick = function(){ setStepResult(idx, 'left'); };
        var bR = document.createElement('button'); bR.className = 'th-act-btn'; bR.textContent = h.tbd ? '📅 日付を入れる' : '📅 リスケ'; // v413
        bR.onclick = function(){ stepReschedule(idx); };
        acts.appendChild(bN); acts.appendChild(bL); acts.appendChild(bR);
      })(i);
      entry.appendChild(acts);
    }
    var del = document.createElement('div');
    del.className = 'th-del';
    del.textContent = 'x';
    (function(idx) {
      del.onclick = function() {
        var m2 = getTraineeMember();
        if (m2 && m2.traineeHistory) { var _hx = m2.traineeHistory[idx]; m2.traineeHistory.splice(idx, 1); try { _tsUnlink(m2, _hx); } catch (eU) {} m2.traineeStatus = getLatestStatus(m2); renderTraineeHistory(null); autoSave(); } // v570
      };
    })(i);
    entry.appendChild(del);
    timeline.appendChild(entry);
  });
  wrap.appendChild(timeline);
  updateStepFlow(hist);
  updateStepFlow(hist);
}

// v413: 予定ステップのリスケ（新しい日付 or 日程未定）。予定のまま維持し、回数と元の日付を記録する
function stepReschedule(idx) {
  var m = getTraineeMember();
  if (!m || !m.traineeHistory || !m.traineeHistory[idx]) return;
  var h = m.traineeHistory[idx];
  closeStepResched();
  var ov = document.createElement('div'); ov.className = 'ms-overlay'; ov.id = 'stepRsOv';
  ov.style.zIndex = '600';
  ov.onclick = function(e){ if (e.target === ov) closeStepResched(); };
  var t9 = new Date();
  var today9 = t9.getFullYear() + '-' + String(t9.getMonth() + 1).padStart(2, '0') + '-' + String(t9.getDate()).padStart(2, '0');
  ov.innerHTML = '<div class="ms-sheet"><div class="ms-grip"></div>'
    + '<div class="ms-hd"><div class="ms-hinfo"><div class="ms-name">🔄 ' + evEsc(h.status || '') + ' をリスケ</div>'
    + '<div style="font-size:11px;color:var(--text-dim)">' + (h.date ? '現在の予定日：' + evEsc(h.date) : '日付未設定') + (h.rs ? '・これまで' + h.rs + '回リスケ' : '') + '</div></div>'
    + '<span class="ms-x" onclick="closeStepResched()">✕</span></div>'
    + '<div style="padding:4px 16px 18px">'
    + '<label class="fl">新しい日付</label>'
    + '<input class="fi" id="_rsDate" type="date" value="' + evEsc(h.tbd ? today9 : (h.date || today9)) + '" style="margin-bottom:10px">'
    + '<button class="btn-p" style="width:100%;padding:12px;font-size:14px" onclick="stepReschedDo(' + idx + ',false)">この日に変更</button>'
    + '<button class="fol-add" style="margin-top:8px" onclick="stepReschedDo(' + idx + ',true)">📅 日程未定（あとで決める）</button>'
    + '</div></div>';
  document.body.appendChild(ov);
  requestAnimationFrame(function(){ ov.classList.add('show'); });
}
function closeStepResched() {
  var ov = document.getElementById('stepRsOv');
  if (ov) { ov.classList.remove('show'); setTimeout(function(){ if (ov.parentNode) ov.parentNode.removeChild(ov); }, 200); }
}
function stepReschedDo(idx, tbd) {
  var m = getTraineeMember();
  if (!m || !m.traineeHistory || !m.traineeHistory[idx]) return;
  var h = m.traineeHistory[idx];
  var nd = ((document.getElementById('_rsDate') || {}).value || '');
  if (!tbd && !nd) { toast('日付を選んでください'); return; }
  // v415: リスケ回数は「決まっていた日程が流れた時」だけ数える。
  //       日程調整中(tbd)の記録に日付を入れる操作は“保留中のリスケの日程が決まっただけ”なので数えない
  //       （元の日付も既に記録済みなので二重に積まない）
  var wasTbd = !!h.tbd;
  try { _tsUnlink(m, h); } catch (eU) {} // v570: 研修履歴でリスケした記録は予定から切り離す
  if (!wasTbd) {
    h.rs = (h.rs || 0) + 1;
    h.rsFrom = (h.rsFrom || []);
    if (h.date) h.rsFrom.push(h.date);
  }
  h.result = 'planned';
  if (tbd) {
    h.tbd = true;
    if (!wasTbd) h.rsAt = new Date().toISOString(); // 調整中になった日（経過日数の警告用。既に調整中なら維持）
  } else {
    h.tbd = false;
    h.rsAt = '';
    h.date = nd;
    m.nextDate = nd;
  }
  autoSave();
  closeStepResched();
  renderTraineeHistory(null);
  toast(tbd ? '🔄 日程調整中にしました（決まったら「📅 日付を入れる」から）'
            : (wasTbd ? '📅 ' + nd + ' に日程が決まりました' : '🔄 ' + nd + ' にリスケしました'));
}
// v472: 研修の離脱（流れた）確定 → 研修結果「流れた」・カテゴリOUTに自動同期（研修生カテゴリの人のみ）
function _traineeDropOut(m) {
  try {
    var t9 = (m.title || '').trim();
    if (t9 && t9 !== 'OUT' && detectCategory(t9) !== '研修生' && !m.trainee) return; // LOI以降は自動変更しない
    m.traineeResult = '流れた';
    m.trainee = false;
    m.title = 'OUT';
    if (typeof selTraineeResultChip === 'function') selTraineeResultChip('流れた');
    if (typeof selCategory === 'function') selCategory('OUT'); // 編集モーダルの表示も同期
    try { _reapproachAdd(m); } catch(eR9) {}
    setTimeout(function(){ toast('✗ 流れた：研修結果を「流れた」・カテゴリを「OUT」にしました（再アプローチリストに登録）'); }, 700);
  } catch(e) {}
}
// 予定ステップの結果を後から確定（進んだ/流れた）
function setStepResult(idx, result) {
  var m = getTraineeMember();
  if (!m || !m.traineeHistory || !m.traineeHistory[idx]) return;
  m.traineeHistory[idx].result = result;
  m.traineeHistory[idx].tbd = false; // v413: 結果が確定したら「日程調整中」は解除
  // v401: BPCの予定を「進んだ」で確定した時も研修結果を自動でBCに
  if (m.traineeHistory[idx].status === 'BPC' && result === 'next' && m.traineeResult !== 'BC') {
    m.traineeResult = 'BC';
    if (typeof selTraineeResultChip === 'function') selTraineeResultChip('BC');
    setTimeout(function(){ toast('✅ BPC実施 → 研修結果を自動でBCにしました'); }, 900);
  }
  m.traineeStatus = getLatestStatus(m);
  syncTraineeTitle(m); // 予定→進んだ確定時もタイトルへ反映
  if (result === 'left') _traineeDropOut(m); // v472: 流れた→研修結果・カテゴリを自動同期
  autoSave();
  renderTraineeHistory(null);
  if (typeof getGame === 'function') getGame().stepUpdatedDate = gameToday();
  if (typeof gameCheck === 'function') gameCheck();
  toast(result === 'left' ? '流れたに確定しました' : '進んだに確定しました 🎉');
  if (result === 'left') { try { renderCurrentView(); } catch(e9) {} }
}
function updateStepFlow(hist) {
  var reached = {};
  (hist || []).forEach(function(h) { reached[h.status] = true; });
  var btns = Array.prototype.slice.call(document.querySelectorAll('.step-btn'));
  for (var i=0; i<btns.length; i++) {
    var label = btns[i].textContent.trim();
    if (reached[label]) {
      btns[i].style.background = 'var(--accent-dim)';
      btns[i].style.borderColor = 'var(--accent)';
      btns[i].style.color = 'var(--accent)';
    } else {
      btns[i].style.background = '';
      btns[i].style.borderColor = '';
      btns[i].style.color = '';
    }
  }
}

function getLatestStatus(m) {
  var hist = (m.traineeHistory || []).filter(function(h){ return !h.ir; }); // v401: フォロー記録はステータスにしない
  return hist.length > 0 ? hist[hist.length-1].status : '';
}

// 研修結果チップ選択
function selTraineeResultChip(val) {
  var hidden = document.getElementById('fTraineeResult');
  if (hidden) hidden.value = val;
  var bcNote = document.getElementById('bcCatNote');
  if (bcNote) bcNote.style.display = (val === 'BC') ? '' : 'none';
  var map = {rcNone:'', rcBC:'BC', rcUser:'ユーザー', rcNG:'流れた'};
  var keys = ['rcNone','rcBC','rcUser','rcNG'];
  for (var i=0; i<keys.length; i++) {
    var el = document.getElementById(keys[i]);
    if (!el) continue;
    el.classList.remove('sel-next','sel-left');
    el.style.cssText = '';
    if (map[keys[i]] === val) {
      if (keys[i] === 'rcBC') el.classList.add('sel-next');
      else if (keys[i] === 'rcNG') el.classList.add('sel-left');
      else { el.style.background = 'var(--surface3)'; el.style.borderColor = 'var(--accent)'; el.style.color = 'var(--accent)'; }
    }
  }
}

// ステップ選択 → 詳細パネル表示
var _selectedStep = '';
function selectStep(step) {
  _selectedStep = step;
  var btns = Array.prototype.slice.call(document.querySelectorAll('.step-btn'));
  for (var i=0; i<btns.length; i++) {
    btns[i].classList.toggle('active', btns[i].textContent.trim() === step);
  }
  var panel = document.getElementById('stepDetailPanel');
  if (!panel) return;
  var today = new Date();
  var todayStr = today.getFullYear() + '-' + String(today.getMonth()+1).padStart(2,'0') + '-' + String(today.getDate()).padStart(2,'0');
  panel.style.display = '';
  panel.innerHTML = '<div class="step-detail">'
    + '<div class="step-detail-hdr"><span class="step-detail-badge">' + step + '</span><span style="font-size:12px;color:var(--text-dim)"> の記録を追加</span></div>'
    + '<div style="display:flex;gap:8px;margin-bottom:10px">'
    + '<div style="flex:1"><label class="fl">日付</label><input class="fi" id="fHistoryDate" type="date" value="' + todayStr + '" style="font-size:14px;padding:8px" onchange="this.blur()"></div>'
    + '<div style="flex:1"><label class="fl">Aさん</label><input class="fi" id="fHistoryASan" type="text" placeholder="名前" style="font-size:14px;padding:8px"></div>'
    + '</div>'
    + '<div style="margin-bottom:12px"><label class="fl" style="margin-bottom:6px">状態</label>'
    + '<div style="display:flex;gap:6px">'
    + '<div class="result-chip sel-plan" id="sdPlan" onclick="selDetailResult(\'planned\')" style="flex:1;justify-content:center">📅 予定</div>'
    + '<div class="result-chip" id="sdNext" onclick="selDetailResult(\'next\')" style="flex:1;justify-content:center">✓ 進んだ</div>'
    + '<div class="result-chip" id="sdLeft" onclick="selDetailResult(\'left\')" style="flex:1;justify-content:center">✗ 流れた</div>'
    + '</div></div>'
    + '<button class="btn-p" style="width:100%;padding:10px;font-size:14px" onclick="confirmAddHistory()">追加する</button>'
    + '</div>';
  window._detailResult = 'planned';
}
function selDetailResult(val) {
  window._detailResult = val;
  var p = document.getElementById('sdPlan');
  var n = document.getElementById('sdNext');
  var l = document.getElementById('sdLeft');
  if (p) { p.classList.remove('sel-plan'); if (val==='planned') p.classList.add('sel-plan'); }
  if (n) { n.classList.remove('sel-next'); if (val==='next') n.classList.add('sel-next'); }
  if (l) { l.classList.remove('sel-left'); if (val==='left') l.classList.add('sel-left'); }
}
// ③二度手間解消：研修ステップを記録したら、研修生カテゴリの間はタイトルを最新ステップに自動同期
function syncTraineeTitle(m) {
  try {
    var t = (m.title || '').trim();
    if (t && detectCategory(t) !== '研修生') return; // LOI以降・BR等は触らない
    var steps = TITLE_OPTIONS['研修生'] || [];
    var best = -1;
    (m.traineeHistory || []).forEach(function(h) {
      if (h.result === 'planned') return; // 予定はまだ進んでいない
      var i = steps.indexOf(h.status);
      if (i > best) best = i;
    });
    if (best >= 0 && steps[best] !== t) {
      m.title = steps[best];
      var ft = document.getElementById('fTitle');
      if (ft) ft.value = m.title; // 編集モーダルが開いていれば基本タブの表示も揃える
    }
  } catch(e) {}
}
function confirmAddHistory() {
  if (!_selectedStep) return;
  var m = getTraineeMember();
  if (!m) return;
  if (!m.traineeHistory) m.traineeHistory = [];
  var dateEl = document.getElementById('fHistoryDate');
  var asanEl = document.getElementById('fHistoryASan');
  var date = dateEl ? dateEl.value : '';
  var aSan = asanEl ? asanEl.value.trim() : '';
  if (!date) {
    var today = new Date();
    date = today.getFullYear() + '-' + String(today.getMonth()+1).padStart(2,'0') + '-' + String(today.getDate()).padStart(2,'0');
  }
  var addedStep = _selectedStep;
  var res = window._detailResult || 'planned';
  m.traineeHistory.push({ status: addedStep, date: date, aSan: aSan, result: res });
  // v401: BPC（製品選び・クロージング・決済）を実施済みで記録したら、研修結果を自動でBCに
  if (addedStep === 'BPC' && res === 'next' && m.traineeResult !== 'BC') {
    m.traineeResult = 'BC';
    if (typeof selTraineeResultChip === 'function') selTraineeResultChip('BC');
    setTimeout(function(){ toast('✅ BPC実施 → 研修結果を自動でBCにしました'); }, 900);
  }
  // 予定なら次回予定として同期（気になるメンバーの「予定なし」に出さない）
  if (res === 'planned') { m.nextDate = date; if (aSan) m.aSan = aSan; }
  m.traineeStatus = getLatestStatus(m);
  syncTraineeTitle(m); // タイトル欄への二度目の入力を不要に
  if (res === 'left') _traineeDropOut(m); // v472: 流れた→研修結果・カテゴリを自動同期
  autoSave();
  renderTraineeHistory(null);
  toast(addedStep + (res === 'planned' ? ' の予定を追加しました' : ' を追加しました'));
  getGame().stepUpdatedDate = gameToday(); // 何日の分でも、今日更新したらミッション達成
  gameCheck();
  var panel = document.getElementById('stepDetailPanel');
  if (panel) panel.style.display = 'none';
  _selectedStep = '';
  var btns = Array.prototype.slice.call(document.querySelectorAll('.step-btn'));
  for (var i=0; i<btns.length; i++) btns[i].classList.remove('active');
}

// v401: フォロー記録（ごはん・個別対応などステップ外のイレギュラー対応。ファネル集計・ステータスには影響しない）
