    ev.recs.forEach(function(x) { if (!x.rec.hostOnly) have[x.mid] = 1; });
    var ids = ev.order.filter(function(id) { return have[id]; });
    ev.recs.forEach(function(x) { if (!x.rec.hostOnly && ids.indexOf(x.mid) < 0) ids.push(x.mid); });
