            + (clickable ? 'cursor:pointer;background:var(--surface2);border:1px solid var(--border2)' : 'opacity:.6;border:1px solid transparent');
          cell.innerHTML = '<div style="font-family:Inter,IBM Plex Mono,monospace;font-size:20px;font-weight:700;color:' + t.col + '">' + t.n + (clickable ? '<span style="font-size:11px;color:var(--text-mid)"> ›</span>' : '') + '</div>'
            + '<div style="font-size:10px;color:var(--text-dim)">' + t.lbl + '</div>';
          if (clickable) cell.onclick = (function(tt){ return function(){ showTraineeDrill(asan, tt.cat, tt.list); }; })(t);
          summary.appendChild(cell);
