          if (stepHists.length === 0) return;
          var nextCount = stepHists.filter(function(h){ return h.result === 'next'; }).length;
          var stTotal = stepHists.length;
          var nextRate = stTotal > 0 ? Math.round(nextCount/stTotal*100) : 0;
          var stepRow = document.createElement('div');
          stepRow.style.cssText = 'display:flex;align-items:center;gap:6px;margin-bottom:4px';
          stepRow.innerHTML = '<div style="width:32px;font-size:11px;color:var(--text-dim);font-family:Inter,IBM Plex Mono,monospace">' + step + '</div>'
            + '<div style="flex:1;background:var(--surface3);border-radius:3px;height:14px;overflow:hidden">'
            + '<div style="background:var(--accent);opacity:0.7;height:100%;width:' + nextRate + '%;border-radius:3px"></div></div>'
            + '<div style="font-size:11px;font-family:Inter,IBM Plex Mono,monospace;color:var(--accent);width:32px;text-align:right">' + nextCount + '</div>'
            + '<div style="font-size:10px;color:var(--text-dim);width:10px;text-align:center">/</div>'
