          if (bc>0)   barEl.innerHTML += '<div style="flex:'+bc+';background:#2CE5B8"></div>';
          if (user>0) barEl.innerHTML += '<div style="flex:'+user+';background:#FFB454"></div>';
          if (ng>0)   barEl.innerHTML += '<div style="flex:'+ng+';background:#FF5D73"></div>';
          if (inProg>0) barEl.innerHTML += '<div style="flex:'+inProg+';background:var(--border2)"></div>';
