      var hc = document.getElementById('statsCol' + firstCol);
      if (tblWrap) tblWrap.scrollLeft = hc ? Math.max(0, hc.offsetLeft - 90) : 0;
      if (plWrap) plWrap.scrollLeft = tblWrap ? tblWrap.scrollLeft : 0;
