// ── v462: 登録月の年・月セレクト＋手入力コンボ ──
// 'YYYY-MM' へ正規化（'2026-09' '2026.9' '2026/9' '202609' 全角も可）。空='' / 不正=null
function _normYm(v) {
  v = String(v || '').trim().replace(/[０-９]/g, function(c){ return String.fromCharCode(c.charCodeAt(0) - 65248); }).replace(/[．／]/g, '.');
  if (!v) return '';
  var m = /^(\d{4})[-.\/]?(\d{1,2})$/.exec(v);
  if (!m) return null;
  var y = parseInt(m[1], 10), mo = parseInt(m[2], 10);
  if (mo < 1 || mo > 12) return null;
  return y + '-' + String(mo).padStart(2, '0');
}
function _startYmBuild() {
  var ys = document.getElementById('fStartY'), ms = document.getElementById('fStartM');
  if (!ys || !ms || ys.options.length) return;
  var nowY = new Date().getFullYear();
  var h = '<option value="">年</option>';
  for (var y = nowY + 1; y >= 2000; y--) h += '<option value="' + y + '">' + y + '</option>';
  ys.innerHTML = h;
  var h2 = '<option value="">月</option>';
  for (var mo = 1; mo <= 12; mo++) h2 += '<option value="' + mo + '">' + mo + '月</option>';
  ms.innerHTML = h2;
}
// 手入力欄の値をセレクトへ反映（開いた時・復元時に呼ぶ）
function syncStartSelects() {
  _startYmBuild();
  var ys = document.getElementById('fStartY'), ms = document.getElementById('fStartM');
  var inp = document.getElementById('fStartMonth');
  if (!ys || !ms || !inp) return;
  var v = _normYm(inp.value);
  if (v) { ys.value = String(parseInt(v.slice(0, 4), 10)); ms.value = String(parseInt(v.slice(5), 10)); }
  else { ys.value = ''; ms.value = ''; }
}
// セレクト操作 → 手入力欄へ（年・月が揃った時に確定。両方空でクリア）
function startYmSel() {
  var ys = document.getElementById('fStartY'), ms = document.getElementById('fStartM');
  var inp = document.getElementById('fStartMonth');
  if (!ys || !ms || !inp) return;
  if (ys.value && ms.value) inp.value = ys.value + '-' + String(parseInt(ms.value, 10)).padStart(2, '0');
  else if (!ys.value && !ms.value) inp.value = '';
}
// 手入力 → 整形してセレクトへ
function startYmManual(v) {
  var inp = document.getElementById('fStartMonth');
  var n = _normYm(v);
  if (n === null) {
    toast('\u26A0\uFE0F 登録月は「2026-09」の形式で入力してください');
    if (inp) inp.value = '';
    syncStartSelects();
    return;
  }
  if (inp) inp.value = n;
  syncStartSelects();
}
