// v437: 手動リスタート設定（既にロールアップ相当の組み替えを済ませたメンバー用）
function _restartRowRender(m) {
  var row = document.getElementById('restartRow'), ctl = document.getElementById('restartCtl');
  if (!row || !ctl) return;
  if (!m || !editingId) { row.style.display = 'none'; return; }
  var t9 = (m.title || '').trim();
  var show = (m.rollup && m.rollup.at) || (!isBROrAbove(t9) && t9 !== 'OUT');
  row.style.display = show ? '' : 'none';
  if (!show) return;
  if (m.rollup && m.rollup.at) {
    var n = _restartMonths(m);
    ctl.innerHTML = '<span style="color:#FB923C;font-weight:700">開始 ' + evEsc(String(m.rollup.at)) + '（' + (n >= 1 ? (n + 'ヶ月目' + (n > 6 ? '・表示終了' : '')) : '開始前') + '）</span>'
      + '<span onclick="memberRestartClear(\'' + m.id + '\')" style="margin-left:10px;padding:4px 12px;border:1px solid var(--border);border-radius:12px;cursor:pointer;font-size:11.5px">解除</span>';
  } else {
    ctl.innerHTML = '<span onclick="memberRestartSet(\'' + m.id + '\')" style="display:inline-block;padding:5px 13px;border:1px solid var(--accent);border-radius:12px;cursor:pointer;font-weight:700;color:var(--accent)">＋ リスタート表示を設定</span>';
  }
}
function memberRestartSet(mid) {
  var m = null;
  for (var i = 0; i < state.members.length; i++) { if (state.members[i].id === mid) { m = state.members[i]; break; } }
  if (!m) return;
  var def = (state.currentMonth || currentMonthStr()).replace('.', '-');
  var v = prompt('リスタート開始月（BRから降格した月）を YYYY-MM で入力\n例：2026-08', def);
  if (!v) return;
  v = v.trim().replace('.', '-').replace('/', '-');
  if (!/^\d{4}-\d{1,2}$/.test(v)) { toast('YYYY-MM の形式で入力してください'); return; }
  var pp = v.split('-');
  m.rollup = { at: pp[0] + '.' + evPad2(parseInt(pp[1], 10)), kids: (m.rollup && m.rollup.kids) || [], fromTitle: (m.rollup && m.rollup.fromTitle) || 'BR', manual: true };
  autoSave();
  _restartRowRender(m);
  renderCurrentView();
  toast('🔄 リスタート表示を設定しました（' + m.rollup.at + ' 開始）');
}
function memberRestartClear(mid) {
  var m = null;
  for (var i = 0; i < state.members.length; i++) { if (state.members[i].id === mid) { m = state.members[i]; break; } }
  if (!m || !m.rollup) return;
  if (!confirm('🔄 リスタート表示を解除しますか？')) return;
  m.rollup = '';
  autoSave();
  _restartRowRender(m);
  renderCurrentView();
  toast('解除しました');
}

