// ── TOAST ──
function toast(msg, dur) {
  if (dur === undefined) dur = 2200;
  var el = document.getElementById('toast');
  el.style.pointerEvents = 'none';
  el.textContent = msg; el.classList.add('show');
  setTimeout(function(){el.classList.remove('show');}, dur);
}
// アクション付きトースト（例：記録直後の「取り消す」）。親指の届く位置でリカバリー可能に
function toastAction(msg, label, fn, dur) {
  if (dur === undefined) dur = 3500;
  window._gmUndoFn = fn || null; window._gmUndoAt = Date.now(); // 直前の取り消し操作を保持（トーストの「↩取消」用）
  var el = document.getElementById('toast');
  el.style.pointerEvents = 'auto'; // v350: .toastはpointer-events:noneのためボタンが押せなかった不具合を修正
  el.innerHTML = evEsc(msg) + ' <span id="_toastAct" style="display:inline-block;margin-left:10px;padding:6px 14px;border-radius:14px;background:var(--surface3);color:var(--accent);font-weight:800;cursor:pointer">' + evEsc(label) + '</span>';
  var a = document.getElementById('_toastAct');
  if (a) a.onclick = function(e){ e.stopPropagation(); el.classList.remove('show'); el.textContent=''; if (fn) fn(); };
  el.classList.add('show');
  setTimeout(function(){ el.classList.remove('show'); setTimeout(function(){ if(!el.classList.contains('show')) el.textContent=''; }, 300); }, dur);
}

