function _p2DrYmLabel(ym) { var p = String(ym).split('-'); return p[0] + '年' + parseInt(p[1], 10) + '月'; }
// 閲覧側の再描画（統計＋期間フィルタ＋リストのみ。入力モーダルには一切触らない）
function _p2DrSync() {
  var side = document.getElementById('p2DrSide');
  var listEl = document.getElementById('p2DrList');
  if (!side || !listEl) return;
  var dreams = _p2().dreams;
  var total = dreams.length, done = 0, amtAll = 0, amtDone = 0;
  dreams.forEach(function(d) { var a = parseFloat(d.amt) || 0; amtAll += a; if (d.done) { done++; amtDone += a; } });
  var pct = total ? Math.round(done / total * 100) : 0;
  var fmt = function(v) { return (Math.round(v * 10) / 10).toLocaleString(); };
  var h = '<div class="p2d-head" style="margin-bottom:0"><div style="display:flex;justify-content:space-between;font-size:13px;font-weight:800"><span>達成 <span style="color:var(--accent);font-size:18px">' + done + '</span> / ' + total + '</span><span>' + pct + '%</span></div>'
    + '<div class="p2d-bar"><i style="width:' + pct + '%"></i></div>'
    + '<div class="p2-meta">💰 総合計 ' + fmt(amtAll) + '万円<br>✅ 達成済み ' + fmt(amtDone) + '万円<br>📋 残り必要 <b style="color:var(--accent)">' + fmt(amtAll - amtDone) + '万円</b></div>';
  var dls = {};
  dreams.forEach(function(d) { if (d.dl && !d.done) dls[d.dl] = true; });
  var sortedDl = Object.keys(dls).sort();
  h += '<div style="display:flex;align-items:center;gap:8px;margin-top:10px"><span style="font-size:13px">📅</span>'
    + '<select class="fi" style="flex:1;padding:8px 10px;font-size:12.5px" onchange="p2DrPeriodChange(this.value)">'
    + '<option value="">期間を選択...</option>'
    + sortedDl.map(function(dl) { return '<option value="' + dl + '"' + (_p2DrPeriod === dl ? ' selected' : '') + '>' + _p2DrYmLabel(dl) + 'まで</option>'; }).join('')
    + '</select></div>';
  if (_p2DrPeriod) {
    var pAmt = 0;
    dreams.forEach(function(d) { if (!d.done && d.dl && d.dl <= _p2DrPeriod) pAmt += parseFloat(d.amt) || 0; });
    h += '<div class="p2-meta" style="margin-top:6px">🎯 ' + _p2DrYmLabel(_p2DrPeriod) + 'までに必要 <b style="color:var(--accent);font-size:14px">' + fmt(pAmt) + '万円</b></div>';
  }
  h += '</div><span class="p2dr-addbtn" onclick="p2DrFormOpen()">＋ 夢を追加</span>';
  side.innerHTML = h;
  var tw = document.getElementById('p2DrTabW'), td = document.getElementById('p2DrTabD');
  if (tw) tw.classList.toggle('on', _p2DrCat === 'want');
  if (td) td.classList.toggle('on', _p2DrCat === 'do');
  // リスト（期日が近い順→期日なし→達成済み）
  var list = dreams.filter(function(d) {
    if (d.cat !== _p2DrCat) return false;
    if (_p2DrPeriod && !d.done && (!d.dl || d.dl > _p2DrPeriod)) return false;
    return true;
  });
  var undone = list.filter(function(d) { return !d.done; }).sort(function(a, b) {
    if (!!a.dl !== !!b.dl) return a.dl ? -1 : 1;
    return (a.dl || '9999').localeCompare(b.dl || '9999');
  });
  var doneL = list.filter(function(d) { return d.done; });
  var rows = undone.concat(doneL);
  var lh = '';
  if (!rows.length) lh = '<div class="p2-meta" style="text-align:center;padding:18px 0;grid-column:1/-1">' + (_p2DrPeriod ? 'この期間の項目はありません' : (_p2DrCat === 'want' ? 'ほしいものを追加しよう！' : 'やりたいことを追加しよう！')) + '</div>';
  rows.forEach(function(d) {
    var meta = [];
    if (d.amt) meta.push('💰 ' + (Math.round(parseFloat(d.amt) * 10) / 10).toLocaleString() + '万円');
    if (d.dl) meta.push('📅 ' + _p2DrYmLabel(d.dl));
    var titleHtml = d.url
      ? '<a href="' + evEsc(d.url) + '" target="_blank" rel="noopener" style="color:#5AD7FF;text-decoration:underline">' + evEsc(d.t) + ' ↗</a>'
      : evEsc(d.t);
    lh += '<div class="p2d-item' + (d.done ? ' done' : '') + '">'
      + '<span class="p2d-chk' + (d.done ? ' on' : '') + '" onclick="p2DrTgl(\'' + d.id + '\')">' + (d.done ? '✓' : '') + '</span>'
      + '<span style="flex:1;min-width:0"><span class="t" style="font-size:14px;font-weight:600">' + titleHtml + '</span>'
      + (meta.length ? '<div class="p2-meta">' + meta.join('　') + '</div>' : '')
      + '</span>'
      + '<span style="color:var(--text-dim);cursor:pointer;flex:none;padding:4px" onclick="p2DrFormOpen(\'' + d.id + '\')">✏️</span>'
      + '<span style="color:var(--text-dim);cursor:pointer;flex:none;padding:4px" onclick="p2DrDel(\'' + d.id + '\')">' + icn('trash') + '</span></div>';
  });
  listEl.innerHTML = lh;
}
function p2DrTab(c) { _p2DrCat = c; _p2DrSync(); }
function p2DrPeriodChange(v) { _p2DrPeriod = v; _p2DrSync(); }
// ── 入力モーダル（追加・編集共通。閲覧側の再描画から独立） ──
