function glForm(title, fields, onSave){
  _glCloseModal();
  var inS='box-sizing:border-box;width:100%;background:var(--surface2);border:1px solid var(--border);border-radius:10px;color:var(--text);padding:11px 12px;font-size:16px;outline:none;-webkit-appearance:none;margin:4px 0 12px;font-family:inherit';
  var lb='font-size:12px;color:var(--text-dim);font-weight:700';
  function ctrl(f,i){
    var id='_gf'+i, v=(f.value==null?'':String(f.value));
    if(f.type==='textarea') return '<textarea id="'+id+'" placeholder="'+evEsc(f.ph||'')+'" style="'+inS+';height:120px;resize:vertical;line-height:1.6">'+evEsc(v)+'</textarea>';
    if(f.type==='select'){ return '<select id="'+id+'" style="'+inS+'">'+(f.options||[]).map(function(o){var val=(typeof o==='object')?o.v:o,l=(typeof o==='object')?o.l:o;return '<option value="'+evEsc(String(val))+'"'+(String(val)===v?' selected':'')+'>'+evEsc(String(l))+'</option>';}).join('')+'</select>'; }
    return '<input id="'+id+'" type="'+(f.type||'text')+'"'+(f.type==='number'?' inputmode="numeric"':'')+' value="'+evEsc(v)+'" placeholder="'+evEsc(f.ph||'')+'" style="'+inS+'">';
  }
  var body='', i=0;
  while(i<fields.length){
    if(fields[i].half && fields[i+1] && fields[i+1].half){
      body+='<div style="display:flex;gap:10px"><div style="flex:1;min-width:0"><label style="'+lb+'">'+evEsc(fields[i].label)+'</label>'+ctrl(fields[i],i)+'</div><div style="flex:1;min-width:0"><label style="'+lb+'">'+evEsc(fields[i+1].label)+'</label>'+ctrl(fields[i+1],i+1)+'</div></div>';
      i+=2;
    } else {
      var f=fields[i];
      body+='<label style="'+lb+'">'+evEsc(f.label)+'</label>'+ctrl(f,i)+(f.hint?'<div style="font-size:10.5px;color:var(--text-dim);margin:-8px 0 12px;line-height:1.5">'+evEsc(f.hint)+'</div>':'');
      i++;
    }
  }
  var ov=document.createElement('div'); ov.className='ms-overlay'; ov.id='glModal';
  ov.onclick=function(e){ if(e.target===ov) _glCloseModal(); };
  ov.innerHTML='<div class="ms-sheet gl-form-sheet" style="max-height:86vh;overflow-y:auto"><div class="ms-grip"></div>'
    +'<div class="ms-hd"><div class="ms-hinfo"><div class="ms-name">'+title+'</div></div><span class="ms-x" onclick="_glCloseModal()">✕</span></div>'
    +'<div style="padding:4px 16px 16px">'+body
    +'<div style="display:flex;gap:9px;margin-top:6px">'
    +'<button type="button" id="_gfSave" style="flex:1;padding:13px;border-radius:11px;border:none;background:var(--accent);color:var(--go-ink);font-size:15px;font-weight:800;cursor:pointer">保存</button>'
    +'<button type="button" onclick="_glCloseModal()" style="flex:none;padding:13px 18px;border-radius:11px;border:1px solid var(--border);background:var(--surface);color:var(--text);font-size:14px;font-weight:700;cursor:pointer">キャンセル</button>'
    +'</div></div></div>';
  document.body.appendChild(ov);
  requestAnimationFrame(function(){ ov.classList.add('show'); });
  document.getElementById('_gfSave').onclick=function(){
    var vals=fields.map(function(f,idx){ var el=document.getElementById('_gf'+idx); return el?el.value:''; });
    // 先に保存処理→ false が返ったら（バリデーション失敗）フォームを閉じず入力を守る
    var r = onSave(vals);
    if (r === false) return;
    _glCloseModal();
  };
  setTimeout(function(){ var first=document.getElementById('_gf0'); if(first && fields[0].type!=='select'){ try{ first.focus(); if(first.select) first.select(); }catch(e){} } }, 260);
}
function glEditGoal(){
  var p=state.goals.plan;
  var keys=Object.keys(p.frontTable||{});
  _glCloseModal();
  var opt=function(sel){ var ks=keys.slice(); if(sel && ks.indexOf(sel)<0) ks.unshift(sel); return '<option value="">未設定</option>'+ks.map(function(k){ return '<option value="'+evEsc(k)+'"'+(k===sel?' selected':'')+'>'+evEsc(k)+'</option>'; }).join(''); };
  var inS='box-sizing:border-box;width:100%;background:var(--surface);border:1px solid var(--border);border-radius:10px;color:var(--text);padding:11px 12px;font-size:15px;outline:none;-webkit-appearance:none;margin:4px 0 12px';
  var lb='font-size:12px;color:var(--text-dim);font-weight:700';
  var autoBox='box-sizing:border-box;width:100%;background:var(--accent-dim,rgba(44,229,184,.1));border:1px solid var(--accent);border-radius:10px;color:var(--accent);padding:11px 12px;font-size:16px;font-weight:800;margin:4px 0 12px;display:flex;align-items:center;justify-content:space-between';
  var initTitle = p.income>0 ? glTitleFromIncome(p.income) : '—';
  var initCnt = (p.adpUnit>0) ? Math.ceil((p.ryutsu||0)/p.adpUnit) : 0;
  var ov=document.createElement('div'); ov.className='ms-overlay'; ov.id='glModal';
  ov.onclick=function(e){ if(e.target===ov) _glCloseModal(); };
  ov.innerHTML='<div class="ms-sheet" style="max-height:88vh;overflow-y:auto">'
    +'<div class="ms-grip"></div>'
    +'<div class="ms-hd"><div class="ms-hinfo"><div class="ms-name">🏔 最重要目標（MY SUMMIT）</div><div style="font-size:11px;color:var(--text-dim)">上から順に入力するだけ。タイトルと客数は自動</div></div><span class="ms-x" onclick="_glCloseModal()">✕</span></div>'
    +'<div style="padding:4px 16px 16px">'
    +'<label style="'+lb+'">① いつまでに</label><input id="_glDl" type="month" value="'+(p.deadline||'')+'" style="'+inS+'">'
    +'<label style="'+lb+'">② 何をする（目標）</label><input id="_glWhat" type="text" placeholder="例: 経済的自由を手に入れる" value="'+evEsc(p.what||'')+'" style="'+inS+'">'
    +'<label style="'+lb+'">③ 必要月収（円）</label><input id="_glInc" type="number" inputmode="numeric" oninput="_glGoalFormRecalc()" placeholder="例: 2000000" value="'+(p.income||'')+'" style="'+inS+'">'
    +'<label style="'+lb+'">必要タイトル（月収から自動判定）</label><div style="'+autoBox+'"><span>🏅 必要タイトル</span><span id="_glTitleAuto">'+evEsc(initTitle)+'</span></div>'
    +'<div style="border-top:1px solid var(--border);margin:2px 0 12px"></div>'
    +'<label style="'+lb+'">④ 必要流通量（P）</label><input id="_glRyutsu" type="number" inputmode="numeric" oninput="_glGoalFormRecalc()" placeholder="3000" value="'+(p.ryutsu||3000)+'" style="'+inS+'">'
    +'<label style="'+lb+'">⑤ 客単価（1人あたりP）</label><input id="_glAdpUnit" type="number" inputmode="numeric" oninput="_glGoalFormRecalc()" placeholder="100" value="'+(p.adpUnit||100)+'" style="'+inS+'">'
    +'<label style="'+lb+'">必要客数（流通量 ÷ 客単価で自動計算）</label><div style="'+autoBox+'"><span>👥 必要客数</span><span id="_glKyakusu">'+(initCnt>0?(initCnt+'人'):'—')+'</span></div>'
    +'<div style="border-top:1px solid var(--border);margin:2px 0 12px"></div>'
    +'<label style="'+lb+'">今の自分のタイトル（進捗表示用・任意）</label><select id="_glTitleNow" style="'+inS+'">'+opt(p.titleNow)+'</select>'
    +'<label style="'+lb+'">今の月収（円・任意）</label><input id="_glIncNow" type="number" inputmode="numeric" placeholder="例: 50000" value="'+(p.incomeNow||'')+'" style="'+inS+'">'
    +'<button type="button" onclick="glSaveGoalModal()" style="width:100%;padding:13px;border-radius:10px;border:none;background:var(--accent);color:var(--go-ink,#08121a);font-size:15px;font-weight:800;margin-top:4px">保存</button>'
    +'</div></div>';
  document.body.appendChild(ov);
  requestAnimationFrame(function(){ ov.classList.add('show'); });
}
// SUMMITフォームのライブ計算（必要タイトル・必要客数）
function _glGoalFormRecalc(){
  var gv=function(id){ var el=document.getElementById(id); return el?String(el.value||'').replace(/[^0-9]/g,''):''; };
  var inc=parseInt(gv('_glInc'),10)||0;
  var td=document.getElementById('_glTitleAuto'); if(td) td.textContent = inc>0 ? glTitleFromIncome(inc) : '—';
  var ry=parseInt(gv('_glRyutsu'),10)||0, unit=parseInt(gv('_glAdpUnit'),10)||0;
  var cnt=unit>0?Math.ceil(ry/unit):0;
  var cd=document.getElementById('_glKyakusu'); if(cd) cd.textContent = cnt>0 ? (cnt+'人') : '—';
}
function glSaveGoalModal(){
  var p=state.goals.plan, g=function(id){ var el=document.getElementById(id); return el?el.value:''; };
  var d=(g('_glDl')||'').trim();
  if(d && !/^\d{4}-\d{2}$/.test(d)){ toast('期限を選び直してください'); return; }
  p.deadline=d;
  p.what=(g('_glWhat')||'').trim();
  p.income=parseInt(String(g('_glInc')).replace(/[^0-9]/g,''),10)||0;
  p.title=p.income>0 ? glTitleFromIncome(p.income) : ''; // 月収から自動判定
  var ry=parseInt(String(g('_glRyutsu')).replace(/[^0-9]/g,''),10); p.ryutsu=(ry>0?ry:3000);
  var unit=parseInt(String(g('_glAdpUnit')).replace(/[^0-9]/g,''),10); p.adpUnit=(unit>0?unit:100);
  p.titleNow=(g('_glTitleNow')||'').trim();
  p.incomeNow=parseInt(String(g('_glIncNow')).replace(/[^0-9]/g,''),10)||0;
  _glCloseModal(); saveGoals(); renderGoals();
}
function glSetPipeline(){
  var p=state.goals.plan;
  glForm('🔁 育成パイプライン',[
    {label:'LOI→BRまでの月数',type:'number',value:p.pipeline,hint:'LOI→Q2→Q3→BR。既定は3ヶ月'}
  ],function(v){
    var n=parseInt(v[0],10);
    if(n>=0&&n<=12){ p.pipeline=n; saveGoals(); renderGoals(); }
    else { toast('0〜12で入力してください'); return false; }
  });
}
function glEditMsDeadline(id){
  var m=(state.goals.milestones||[]).find(function(x){return x.id===id;}); if(!m)return;
  var t=_glProg(m.tmplId)||{};
  glForm('🚩 通過点の条件',[
    {label:'BR必達の年月',type:'month',value:m.brYm||t.brYm||''},
    {label:'到達タイトル',value:m.reqTitle||t.reqTitle||'ルビー',ph:'ルビー など'}
  ],function(v){
    if(v[0]&&!/^\d{4}-\d{2}$/.test(v[0])){ toast('年月を選択してください'); return false; }
    m.brYm=v[0]; if(v[1].trim()) m.reqTitle=v[1].trim();
    saveGoals(); renderGoals();
  });
}
function glFocusToTasks(){
  if(!eventsUid()){ toast('ログインが必要です'); return; }
  var p=state.goals.plan, mF=_glMonthlyFront(p);
  var parts=GL_STAGES.map(function(s){ return s.label.replace(/（.*）/,'')+(mF*(p.funnel[s.k]||0)); });
  var e={ id:genEventId(), type:'task', title:'今月の行動目標：フロント'+mF+'人（'+parts.join('・')+'）', date:evTodayYmd(), done:false, memberId:'', categoryId:'', priority:'normal', memo:'', createdAt:new Date().toISOString() };
  state.events.push(e); saveEventDoc(e); if(typeof updateEventsBadge==='function') updateEventsBadge();
  toast('今日のタスクに追加しました ✓');
}
function glSetFrontTable(){
  var p=state.goals.plan; var keys=Object.keys(p.frontTable);
  var fields=keys.map(function(k){ return {label:k,type:'number',value:p.frontTable[k],half:true}; });
  fields.push({label:'理想フロント数（空欄=必達と同じ）',type:'number',value:p.frontIdeal!=null?p.frontIdeal:''});
  fields.push({label:'今月つくるフロント数（空欄=自動計算）',type:'number',value:p.monthlyFront!=null?p.monthlyFront:''});
  glForm('👥 タイトル→必要フロント数',fields,function(v){
    keys.forEach(function(k,i){ var n=parseInt(v[i],10); if(!isNaN(n)) p.frontTable[k]=n; });
    p.frontIdeal = v[keys.length].trim()===''?null:(parseInt(v[keys.length],10)||0);
    p.monthlyFront = v[keys.length+1].trim()===''?null:(parseInt(v[keys.length+1],10)||0);
    saveGoals(); renderGoals();
  });
}
function glSetAdp(){
  var p=state.goals.plan;
  glForm('🛒 流通とADP',[
    {label:'流通の目標ポイント',type:'number',value:p.ryutsu,half:true},
    {label:'1 ADPあたりのポイント',type:'number',value:p.adpUnit,half:true}
  ],function(v){
    p.ryutsu=parseInt(String(v[0]).replace(/[^0-9]/g,''),10)||0;
    p.adpUnit=parseInt(String(v[1]).replace(/[^0-9]/g,''),10)||100;
    saveGoals(); renderGoals();
  });
}
function glSetFunnel(){
  var p=state.goals.plan;
  var fields=GL_STAGES.map(function(st){ return {label:st.label,type:'number',value:p.funnel[st.k],half:true}; });
  glForm('係数（フロント1人あたりの必要数）',fields,function(v){
    GL_STAGES.forEach(function(st,i){ var n=parseInt(v[i],10); if(!isNaN(n)) p.funnel[st.k]=n; });
    saveGoals(); renderGoals();
  });
}
function glSetActual(stage, val){
  var p=state.goals.plan; var ym=_glCurYm();
  p.actuals[ym]=p.actuals[ym]||{};
  p.actuals[ym][stage]=parseInt(String(val).replace(/[^0-9]/g,''),10)||0;
  saveGoals(); renderGoals();
}

