  var waist = Math.round(14 + 6 * pB);
  var legW = Math.round((6 + 2 * pB + 6 * pLeg) * 10) / 10;
  var skin = '#F6C08B', dark = '#E8A968';
  var face = ms.lv >= 9 ? '😎' : ms.lv >= 7 ? '🔥' : ms.lv >= 5 ? '😤' : ms.lv >= 3 ? '🙂' : '🐣';
  var s2 = '<svg width="' + size + '" height="' + size + '" viewBox="-10 0 120 112" style="flex:none">';
  if (ms.lv >= 8) s2 += '<circle cx="50" cy="55" r="48" fill="#FBBF24" opacity="0.14"/><circle cx="50" cy="55" r="38" fill="#FBBF24" opacity="0.12"/>';
  s2 += '<path d="M ' + (50 - sh) + ' 46 Q ' + (50 - sh - 12) + ' 44 ' + (50 - sh - 14) + ' 30" stroke="' + skin + '" stroke-width="' + (arm * 2) + '" fill="none" stroke-linecap="round"/>';
  s2 += '<path d="M ' + (50 + sh) + ' 46 Q ' + (50 + sh + 12) + ' 44 ' + (50 + sh + 14) + ' 30" stroke="' + skin + '" stroke-width="' + (arm * 2) + '" fill="none" stroke-linecap="round"/>';
  s2 += '<circle cx="' + (50 - sh - 14) + '" cy="27" r="' + (arm * 0.85) + '" fill="' + skin + '"/>';
  s2 += '<circle cx="' + (50 + sh + 14) + '" cy="27" r="' + (arm * 0.85) + '" fill="' + skin + '"/>';
  s2 += '<circle cx="' + (50 - sh - 7) + '" cy="41" r="' + (arm * 0.75) + '" fill="' + dark + '" opacity="0.55"/>';
  s2 += '<circle cx="' + (50 + sh + 7) + '" cy="41" r="' + (arm * 0.75) + '" fill="' + dark + '" opacity="0.55"/>';
  s2 += '<path d="M ' + (50 - sh) + ' 40 Q 50 ' + (36 - pC * 4) + ' ' + (50 + sh) + ' 40 L ' + (50 + waist) + ' 72 Q 50 78 ' + (50 - waist) + ' 72 Z" fill="' + skin + '"/>';
  s2 += '<ellipse cx="' + (50 - chest * 0.62) + '" cy="50" rx="' + chest * 0.62 + '" ry="' + chest * 0.5 + '" fill="' + dark + '" opacity="0.5"/>';
  s2 += '<ellipse cx="' + (50 + chest * 0.62) + '" cy="50" rx="' + chest * 0.62 + '" ry="' + chest * 0.5 + '" fill="' + dark + '" opacity="0.5"/>';
