// ── ブラウザ通知（Notification API）──
var _notifiedTriggers = {};   // 同一トリガーの二重通知防止（セッション内）
var _reminderTimer = null;

function notifSupported() { return typeof Notification !== 'undefined'; }

function updateNotifBtn() {
  var b = document.getElementById('evNotifBtn');
  if (!b) return;
  if (!notifSupported()) { b.style.display = 'none'; return; }
  b.style.display = '';
  b.classList.remove('on', 'denied');
  if (Notification.permission === 'granted') { b.classList.add('on'); b.textContent = '通知ON'; }
  else if (Notification.permission === 'denied') { b.classList.add('denied'); b.textContent = '通知ブロック中'; }
  else { b.textContent = '通知をオン'; }
}

function requestNotifPermission() {
  if (!notifSupported()) { toast('このブラウザは通知に対応していません'); return; }
  if (Notification.permission === 'granted') {
    toast('通知はすでにオンです');
    updateNotifBtn(); checkReminders(); return;
  }
  if (Notification.permission === 'denied') {
    toast('ブラウザ設定で通知がブロックされています。設定から許可してください');
    updateNotifBtn(); return;
  }
  var handle = function(p) {
    updateNotifBtn();
    if (p === 'granted') {
      toast('通知をオンにしました ');
      showBrowserNotif('通知をオンにしました', '期限・予定の時刻にお知らせします', 'gm-welcome');
      checkReminders();
      // CAL-4: アプリを閉じていても届くプッシュ通知として端末を登録
      fcmRegister().then(function(ok){
        if (ok) toast('この端末をプッシュ通知に登録しました（アプリを閉じていても届きます）');
      });
    } else {
      toast('通知は許可されませんでした');
    }
  };
  // Promise版と旧コールバック版の両対応（iOS Safari等）
  try {
    var res = Notification.requestPermission(handle);
    if (res && typeof res.then === 'function') res.then(handle);
  } catch (err) {
    try { Notification.requestPermission(handle); } catch (e2) {}
  }
}

// v351: 通知タップで該当タスク（1件時）またはToDoの「今日」一覧へ飛ぶ。iOS等はSW経由で表示
function gmOpenDueTodos() {
  switchView('events');
  setEventsMode('agenda');
  _todoNav = { type: 'home' };
  todoSetFilter('today');
}
function showBrowserNotif(title, body, tag, eventId) {
  if (!notifSupported() || Notification.permission !== 'granted') return;
  var opts = { body: body || '', icon: './icon-192.png', badge: './icon-192.png', data: { eventId: eventId || '', todo: !eventId } };
  if (tag) opts.tag = tag;
  var shown = false;
  try {
    var n = new Notification('' + title, opts);
    shown = true;
    n.onclick = function() {
      try { window.focus(); } catch (_) {}
      if (eventId) gmOpenEventFromPush(eventId);
      else gmOpenDueTodos();
      try { n.close(); } catch (_) {}
    };
    setTimeout(function() { try { n.close(); } catch (_) {} }, 12000);
  } catch (err) {}
  if (!shown && ('serviceWorker' in navigator)) {
    // iOSのホーム画面アプリは Notification コンストラクタ不可 → SW経由（タップはsw.jsのnotificationclickが処理）
    try {
      navigator.serviceWorker.ready.then(function(reg){
        return reg.showNotification('' + title, opts);
      }).catch(function(){});
    } catch (e2) {}
  }
}

// 予定の日時オブジェクト（時刻未指定は9:00基準）
function evDateTime(e) {
  if (!e.date) return null;
  var p = e.date.split('-');
  if (p.length !== 3) return null;
  var hh = 9, mm = 0;
  if (e.time) {
    var tp = e.time.split(':');
    hh = parseInt(tp[0], 10) || 0;
    mm = parseInt(tp[1], 10) || 0;
  }
  return new Date(parseInt(p[0],10), parseInt(p[1],10)-1, parseInt(p[2],10), hh, mm, 0, 0);
}

// リマインド通知チェック（60秒ごと＋随時呼び出し）
function checkReminders() {
  if (!notifSupported() || Notification.permission !== 'granted') return;
  // v380: この端末がPUSH登録済みならサーバーからの通知が届くため、アプリ内リマインダーは出さない。
  //（両方生きていると、リマインド時刻にアプリを開いている時に同じ通知が2通届く。
  //  ローカル通知はPUSH未登録・通知オフ端末向けのフォールバックとしてのみ残す）
  try {
    if (localStorage.getItem('gm_pushOff') !== '1' && localStorage.getItem('gm_fcmToken')) return;
  } catch(eDup) {}
  var now = Date.now();
  var GRACE = 5 * 60000; // 予定時刻を5分過ぎたら以降は通知しない
  (state.events || []).forEach(function(e) {
    var rb = e.remindBefore;
    if (rb === undefined || rb === null || rb === '') return;
    if (e.type === 'task' && e.done) return;
    if (e.type === 'task' ? !evTdMine(e) : !evShowMine(e)) return; // v567: 「メンバーのみ」は通知しない
    var dt = evDateTime(e);
    if (!dt) return;
    var evMs = dt.getTime();
    var trigger = evMs - (parseInt(rb, 10) || 0) * 60000;
    var key = e.id + '@' + e.date + (e.time || '') + '#' + rb;
    if (_notifiedTriggers[key]) return;
    if (now >= trigger && now <= evMs + GRACE) {
      _notifiedTriggers[key] = 1;
      var when = e.time ? e.time : fmtEvDate(e.date, '');
      var body = (e.type === 'task' ? 'タスク' : '予定') + '：' + when;
      var m = e.memberId ? findMemberAny(e.memberId) : null;
      if (m) body += ' / ' + ((m.lastName||'') + (m.firstName||'')).trim();
      showBrowserNotif(e.title || '(無題)', body, key);
    }
  });
}

function startReminderLoop() {
  if (_reminderTimer) return;
  _reminderTimer = setInterval(checkReminders, 60000);
}

// ── PWA（インストール / Service Worker）──
var _deferredInstall = null; // beforeinstallprompt（Android/デスクトップChrome）

function isStandalone() {
  return (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches)
    || navigator.standalone === true;
}
function isIOS() {
  return /iPad|iPhone|iPod/.test(navigator.userAgent || '');
}
function updateInstallBtn() {
  var b = document.getElementById('evInstallBtn');
  if (!b) return;
  // インストール済み(standalone)なら隠す。それ以外で、インストール手段がある時だけ表示。
  if (isStandalone()) { b.style.display = 'none'; return; }
  b.style.display = (_deferredInstall || isIOS()) ? '' : 'none';
}
function installPWA() {
  if (_deferredInstall) {
    _deferredInstall.prompt();
    _deferredInstall.userChoice.then(function(res) {
      if (res && res.outcome === 'accepted') toast('ホーム画面に追加しました ✓');
      _deferredInstall = null;
      updateInstallBtn();
    });
    return;
  }
  if (isIOS()) {
    alert('ホーム画面に追加する手順:\n\n1. 画面下の「共有」ボタン（□に↑）をタップ\n2.「ホーム画面に追加」を選択\n\nホーム画面から起動すると全画面のアプリとして使えます。');
    return;
  }
  toast('お使いのブラウザのメニューから「インストール」を選んでください');
}
if (typeof window !== 'undefined') {
  window.addEventListener('beforeinstallprompt', function(e) {
    e.preventDefault();
    _deferredInstall = e;
    updateInstallBtn();
  });
  window.addEventListener('appinstalled', function() {
    _deferredInstall = null;
    toast('アプリをインストールしました 🎉');
    updateInstallBtn();
  });
}
// Service Worker 登録（相対パス → scope は /groove-map/ 配下）
// 新バージョン検知 → 更新バナー（「アプリを再起動して」の案内を撲滅）
function showUpdateBanner() {
  if (document.getElementById('updBanner')) return;
  var b = document.createElement('div'); b.id = 'updBanner';
  b.style.cssText = 'position:fixed;left:50%;transform:translateX(-50%);bottom:calc(env(safe-area-inset-bottom) + 84px);z-index:900;background:var(--surface2);border:1px solid var(--accent);border-radius:24px;padding:9px 16px;font-size:13px;display:flex;gap:12px;align-items:center;box-shadow:var(--shadow);white-space:nowrap';
  b.innerHTML = '<span>🔄 新しいバージョンがあります</span><span style="color:var(--accent);font-weight:800;cursor:pointer" onclick="location.reload()">更新</span>';
  document.body.appendChild(b);
}
window.addEventListener('pagehide', function(){ try { flushPendingSave(); } catch(e){} });
if ('serviceWorker' in navigator) {
  window.addEventListener('load', function() {
    navigator.serviceWorker.register('sw.js').then(function(reg) {
      if (reg.waiting && navigator.serviceWorker.controller) { showUpdateBanner(); return; }
      reg.addEventListener('updatefound', function() {
        var nw = reg.installing;
        if (!nw) return;
        nw.addEventListener('statechange', function() {
          if ((nw.state === 'activated' || nw.state === 'installed') && navigator.serviceWorker.controller) showUpdateBanner();
        });
      });
    }).catch(function() {});
  });
}

