    cx.font = '800 40px "Noto Sans JP", sans-serif';
    cx.fillText('MY TEAM', W / 2, 190);
    cx.fillStyle = ink;
    cx.font = '900 170px "Inter", "IBM Plex Mono", sans-serif';
    cx.fillText(String(_m3Nodes.length), W / 2, 380);
    cx.font = '800 46px "Noto Sans JP", sans-serif';
    cx.fillText('人のなかまたち', W / 2, 460);
