  if (!/^[0-2]?\d:[0-5]\d$/.test(e.time) || parseInt(e.time, 10) > 29) e.time = '';
  if (!/^[0-2]?\d:[0-5]\d$/.test(e.endTime) || parseInt(e.endTime, 10) > 29) e.endTime = '';
  if (e.time && e.endTime && e.endTime < e.time) e.endTime = '';
  // v299: 終日・連日
  e.allDay = !!_evAllDay;
