// ── LTSV詳細 ──
var LTSV_BR_PLUS = ['BR','ゴールド','G','ラピス','L','ルビー','R','エメラルド','E','ダイヤモンド','D','ブルーダイヤモンド','BD','PD','チームエリート'];
// v523: 全員のLTSVを1回の走査で計算（calcLtsv を全員に呼ぶと人数の3乗で重くなるため）
function ltsvMap(allMembers) {
  var kids = {}, byId = {}, memo = {};
  allMembers.forEach(function(m) { byId[m.id] = m; (kids[m.parentId || ''] || (kids[m.parentId || ''] = [])).push(m); });
  var calc = function(id, guard) {
    if (memo[id] !== undefined) return memo[id];
    if (guard > 60) return 0;
    var m = byId[id], t = (m && LTSV_BR_PLUS.indexOf((m.title || '').trim()) >= 0) ? (m.ptCurrent || 0) : 0;
    (kids[id] || []).forEach(function(c) { t += calc(c.id, guard + 1); });
    memo[id] = t;
    return t;
  };
  allMembers.forEach(function(m) { calc(m.id, 0); });
  return memo;
}
function calcLtsv(memberId, allMembers) {
  var total = 0;
  // 本人（BR以上のはず）
  for (var i=0; i<allMembers.length; i++) {
    if (allMembers[i].id === memberId) {
      if (LTSV_BR_PLUS.indexOf((allMembers[i].title||'').trim()) >= 0) total += (allMembers[i].ptCurrent||0);
      break;
    }
  }
  // 配下のBR以上のみ合算
  function walkDown(pid) {
    for (var j=0; j<allMembers.length; j++) {
      if (allMembers[j].parentId === pid) {
        if (LTSV_BR_PLUS.indexOf((allMembers[j].title||'').trim()) >= 0) total += (allMembers[j].ptCurrent||0);
        walkDown(allMembers[j].id);
      }
    }
  }
  walkDown(memberId);
  return total;
}

function showLtsvDetail() {
  var members = membersForMap('current');

  var list = members
    .filter(function(m) {
      // ルート（自分自身＝parentIdが空）を除外
      if (!m.parentId || m.parentId === '') return false;
      // BR以上のみ
      var t = (m.title||'').trim();
      return LTSV_BR_PLUS.indexOf(t) >= 0;
    })
    .map(function(m) {
      return { m: m, ltsv: calcLtsv(m.id, members) };
    });

  list.sort(function(a,b){ return b.ltsv - a.ltsv; });

  var html = '';
  list.forEach(function(item, i) {
    var m = item.m;
    var g = m.gender||'male';
    var col = g==='male' ? 'var(--male)' : 'var(--female)';
    html += '<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--border);cursor:pointer;-webkit-tap-highlight-color:rgba(44,229,184,.1)" onclick="jumpToMember(\'' + m.id + '\')">'
      + '<div style="font-family:Inter,IBM Plex Mono,monospace;font-size:13px;color:var(--text-dim);width:20px;text-align:right">' + (i+1) + '</div>'
      + '<div style="font-size:11px;color:var(--text-dim);font-family:Inter,IBM Plex Mono,monospace;width:36px;flex-shrink:0">' + (m.title||'') + '</div>'
      + '<div style="font-size:13px;font-weight:700;color:' + col + ';flex:1">' + (m.lastName||'') + ' ' + (m.firstName||'') + '</div>'
      + '<div style="font-family:Inter,IBM Plex Mono,monospace;font-size:16px;font-weight:500">' + item.ltsv.toLocaleString() + '</div>'
      + '<div style="font-size:10px;color:var(--text-dim)">→</div>'
      + '</div>';
  });
  var el = document.getElementById('ltsvRankList');
  if (el) el.innerHTML = html || '<div class="empty">BR以上のメンバーがいません</div>';
  var modal = document.getElementById('ltsvModal');
  if (modal) modal.classList.add('open');
}

function closeLtsvModal(e) {
  if (e && e.target !== document.getElementById('ltsvModal')) return;
  var modal = document.getElementById('ltsvModal');
  if (modal) modal.classList.remove('open');
}

function jumpToMember(id) {
  if (!isPCMode()) { var lm = document.getElementById('ltsvModal'); if (lm) lm.classList.remove('open'); mxJump(id); return; } // v607
  // モーダルを閉じる
  var modal = document.getElementById('ltsvModal');
  if (modal) modal.classList.remove('open');

  // 現状MAPに切り替え
  switchView('current');

  // 対象カードまでのパスを展開してスクロール
  setTimeout(function() {
    // 祖先ノードを全部展開（結合ノードも辿れるよう合成リストを使用）。
    // 遅延描画の枝は上（ルート側）から順に実体化しないと下位のDOMが存在しないため、
    // 祖先チェーンを組み立ててルート側から開いていく。
    var members = (typeof composeMergedInto === 'function') ? composeMergedInto(membersForMap('current'), 'current') : state.members;
    var byId = {};
    for (var bi=0; bi<members.length; bi++) byId[members[bi].id] = members[bi];
    var chain = [], cur = byId[id], guard = 0;
    while (cur && cur.parentId && guard++ < 50) { chain.unshift(cur.parentId); cur = byId[cur.parentId]; }
    chain.forEach(function(aid){
      var ch = document.getElementById('ch-' + aid);
      var nw = document.getElementById('nw-' + aid);
      if (ch) {
        if (typeof _lazyBuildChildren === 'function') _lazyBuildChildren(ch, aid);
        if (ch.classList.contains('closed')) {
          ch.classList.remove('closed');
          if (nw) nw.classList.add('open');
        }
        if (window._treeOpen) window._treeOpen[aid] = true;
      }
    });

    // カードをハイライト＆スクロール
    setTimeout(function() {
      var nc = document.getElementById('nc-' + id);
      var nw = document.getElementById('nw-' + id);
      if (!nc) return;

      // 選択状態に
      Array.prototype.slice.call(document.querySelectorAll('.nc.selected')).forEach(function(el){ el.classList.remove('selected'); });
      nc.classList.add('selected');
      selectedParentId = id;

      // スクロール
      nc.scrollIntoView({ behavior: 'smooth', block: 'center' });

      // 一瞬フラッシュ
      nc.style.transition = 'background .1s';
      nc.style.background = 'rgba(44,229,184,0.2)';
      setTimeout(function() {
        nc.style.background = '';
        setTimeout(function() { nc.style.transition = ''; }, 300);
      }, 400);
    }, 100);
  }, 200);
}

// ── ジャンプ検索（階層を保ったままツリー内の本人へ） ──
var _tqsTimer = null;
function treeQuickSearchInput(q) {
  if (_tqsTimer) clearTimeout(_tqsTimer);
  _tqsTimer = setTimeout(function(){ _treeQuickSearchRun(q); }, 120);
}
function _treeQuickSearchRun(q) {
  var drop = document.getElementById('treeQuickSearchDrop');
  if (!drop) return;
  q = (q || '').trim().toLowerCase();
  if (!q) { drop.style.display = 'none'; drop.innerHTML = ''; return; }
  var members = composeMergedInto(membersForMap('current'), 'current');
  var hits = [];
  for (var i = 0; i < members.length && hits.length < 8; i++) {
    var m = members[i];
    if (m.deleted) continue;
    var nm = ((m.lastName||'') + (m.firstName||'') + ' ' + (m.lastName||'') + ' ' + (m.firstName||'')).toLowerCase();
    if (nm.indexOf(q) >= 0) hits.push(m);
  }
  if (!hits.length) {
    drop.innerHTML = '<div style="padding:13px 14px;font-size:13px;color:var(--text-dim)">該当なし</div>';
    drop.style.display = '';
    return;
  }
  drop.innerHTML = hits.map(function(m){
    var nm = ((m.lastName||'') + ' ' + (m.firstName||'')).trim() || '(無名)';
    var foreign = /^MG_/.test(m.id);
    return '<div onclick="treeQuickSearchGo(\'' + m.id + '\')" style="display:flex;align-items:center;justify-content:space-between;padding:13px 14px;border-bottom:1px solid var(--border);cursor:pointer">'
      + '<span><b>' + evEsc(nm) + '</b><small style="color:var(--text-dim);margin-left:8px">' + evEsc(m.title||'') + (foreign ? ' ・🔗結合' : '') + '</small></span>'
      + '<span style="color:var(--accent);font-size:12px">ここへ ›</span></div>';
  }).join('');
  drop.style.display = '';
}
function treeQuickSearchGo(id) {
  var drop = document.getElementById('treeQuickSearchDrop');
  var inp = document.getElementById('treeQuickSearch');
  if (drop) { drop.style.display = 'none'; drop.innerHTML = ''; }
  if (inp) { inp.value = ''; inp.blur(); }
  jumpToMember(id);
}

// ── 検索 ──
var searchMode = 'OR';
var searchFilters = { freeword:'', activity:[], morale:[], category:[], gender:[], trainee:[], gsvMin:'', gsvMax:'', aSan:'', nextDate:'' };

function openSearchModal() {
  // 条件が空なら空の条件を1つ追加（プレースホルダー表示）
  if (searchConds.length === 0) {
    searchConds.push({ field:'', value:'' });
  }
  renderSearchConds();
  var modal = document.getElementById('searchModal');
  if (modal) modal.classList.add('open');
}

function closeSearchModal(e) {
  if (e && e.target !== document.getElementById('searchModal')) return;
  var modal = document.getElementById('searchModal');
  if (modal) modal.classList.remove('open');
  applyAllFilters();
}

// 検索条件の定義

var CATEGORY_TITLES = {
  '研修生': ['マケ','PG','DLR','EXP','PA','面談','BPC','CO','OUT'],
  'BA':     ['LOI','Q2','Q3','Q4','B1','B2','B3','B4','B5','B6','B7','B8','B9','B10','B11','BM','OUT'],
  'BR':     ['BR','ゴールド','ラピス','ルビー','エメラルド','ダイヤモンド','ブルーダイヤモンド','PD','チームエリート','OUT'],
};

var SEARCH_FIELDS = [
  { key:'freeword',  label:'フリーワード', type:'text',    placeholder:'名前・メモ・タイトルなど' },
  { key:'activity',  label:'稼働',         type:'chips',   options:[{v:'S',l:'S（120%）'},{v:'A',l:'A（仕事辞める日確定）'},{v:'B',l:'B（仕事以外）'},{v:'C',l:'C（来れるけど来ない）'}] },
  { key:'morale',    label:'やる気',       type:'chips',   options:[{v:'1',l:'🌱 パヤパヤ'},{v:'2',l:'💪 やる気'},{v:'3',l:'🔥 死ぬ気'}] },
  { key:'category',  label:'研修生・BA・BR', type:'chips',   options:[{v:'研修生',l:'研修生'},{v:'BA',l:'BA'},{v:'BR',l:'BR'}] },
  { key:'gender',    label:'性別',         type:'chips',   options:[{v:'male',l:'♂ 男性'},{v:'female',l:'♀ 女性'}] },
  { key:'trainee',   label:'研修生',       type:'chips',   options:[{v:'true',l:'研修生のみ'}] },
  { key:'gsvMin',    label:'GSV（最小）',  type:'number',  placeholder:'例：1000' },
  { key:'gsvMax',    label:'GSV（最大）',  type:'number',  placeholder:'例：5000' },
  { key:'aSan',      label:'Aさん',        type:'text',    placeholder:'名前で検索' },
  { key:'nextDate',  label:'次回日時',     type:'text',    placeholder:'日時で検索' },
  { key:'memo',      label:'メモ',         type:'text',    placeholder:'メモで検索' },
];

// 条件リスト（[{field:key, value:...}]）
var searchConds = [];

function addSearchCond() {
  searchConds.push({ field:'', value:'' });
  renderSearchConds();
}

function removeSearchCond(idx) {
  searchConds.splice(idx, 1);
  renderSearchConds();
  applyAllFilters();
}

function onCondFieldChange(idx) {
  var sel = document.getElementById('sf-field-' + idx);
  if (!sel) return;
  searchConds[idx] = { field: sel.value, value: '' };
  renderSearchConds();
}

function onCondValueChange(idx) {
  var el = document.getElementById('sf-val-' + idx);
  if (!el) return;
  searchConds[idx].value = el.value;
  applyAllFilters();
}


function onCondTitleToggle(idx, val) {
  var cond = searchConds[idx];
  if (!cond) return;
  if (!cond.titleValue) cond.titleValue = '';
  var arr = cond.titleValue ? cond.titleValue.split(',').filter(function(v){return v;}) : [];
  var pos = arr.indexOf(val);
  if (pos >= 0) arr.splice(pos, 1); else arr.push(val);
  cond.titleValue = arr.join(',');
  renderSearchConds();
  applyAllFilters();
}

function onCondChipToggle(idx, val) {
  var cond = searchConds[idx];
  if (!cond) return;
  var arr = cond.value ? cond.value.split(',') : [];
  var pos = arr.indexOf(val);
  if (pos >= 0) arr.splice(pos, 1); else arr.push(val);
  cond.value = arr.join(',');
  renderSearchConds();
  applyAllFilters();
}

function renderSearchConds() {
  var wrap = document.getElementById('searchCondList');
  if (!wrap) return;
  wrap.innerHTML = '';

  if (searchConds.length === 0) {
    var emptyDiv = document.createElement('div');
    emptyDiv.style.cssText = 'color:var(--text-dim);font-size:13px;padding:8px 0';
    emptyDiv.textContent = '条件なし。下の＋で追加してください。';
    wrap.appendChild(emptyDiv);
    return;
  }

  searchConds.forEach(function(cond, idx) {
    var def = null;
    for (var di=0; di<SEARCH_FIELDS.length; di++) {
      if (SEARCH_FIELDS[di].key === cond.field) { def = SEARCH_FIELDS[di]; break; }
    }
    if (!def) def = SEARCH_FIELDS[0];

    var box = document.createElement('div');
    box.style.cssText = 'background:var(--surface2);border:1px solid var(--border);border-radius:var(--r);padding:12px;margin-bottom:8px';

    var row = document.createElement('div');
    row.style.cssText = 'display:flex;align-items:center;gap:8px';

    var sel = document.createElement('select');
    sel.className = 'fs';
    sel.style.flex = '1';
    sel.id = 'sf-field-' + idx;

    // プレースホルダー（未選択状態）
    var placeholder = document.createElement('option');
    placeholder.value = '';
    placeholder.textContent = '── 検索カテゴリを選択 ──';
    placeholder.disabled = true;
    if (!cond.field) placeholder.selected = true;
    sel.appendChild(placeholder);

    SEARCH_FIELDS.forEach(function(f) {
      var opt = document.createElement('option');
      opt.value = f.key;
      opt.textContent = f.label;
      if (f.key === cond.field) opt.selected = true;
      sel.appendChild(opt);
    });
    // 未選択時はグレーアウト
    if (!cond.field) sel.style.color = 'var(--text-dim)';
    (function(i){ sel.onchange = function(){ onCondFieldChange(i); }; })(idx);
    row.appendChild(sel);

    var del = document.createElement('div');
    del.style.cssText = 'color:var(--red);font-size:18px;cursor:pointer;padding:0 4px;flex-shrink:0';
    del.textContent = '\u2715';
    (function(i){ del.onclick = function(){ removeSearchCond(i); }; })(idx);
    row.appendChild(del);
    box.appendChild(row);

    if (def.type === 'chips') {
      var chipWrap = document.createElement('div');
      chipWrap.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px;margin-top:8px';
      var selected = cond.value ? cond.value.split(',') : [];
      (def.options||[]).forEach(function(opt) {
        var chip = document.createElement('div');
        chip.className = 'sf-chip' + (selected.indexOf(opt.v) >= 0 ? ' active' : '');
        chip.style.cssText = 'font-size:13px;padding:6px 14px';
        chip.textContent = opt.l;
        (function(i, v){ chip.onclick = function(){ onCondChipToggle(i, v); }; })(idx, opt.v);
        chipWrap.appendChild(chip);
      });
      box.appendChild(chipWrap);

      // カテゴリ選択時：選択されたカテゴリのタイトルチップを追加表示
      if (def.key === 'category' && selected.length > 0) {
        var titleLabel = document.createElement('div');
        titleLabel.style.cssText = 'font-size:10px;color:var(--text-dim);margin:10px 0 4px;letter-spacing:1px;text-transform:uppercase;font-family:Inter,IBM Plex Mono,monospace';
        titleLabel.textContent = 'タイトル';
        box.appendChild(titleLabel);

        var titleWrap = document.createElement('div');
        titleWrap.style.cssText = 'display:flex;flex-wrap:wrap;gap:5px';

        // 選択済みカテゴリのタイトルを集める
        var titleSelected = cond.titleValue ? cond.titleValue.split(',') : [];
        var shownTitles = {};
        selected.forEach(function(cat) {
          var titles = CATEGORY_TITLES[cat] || [];
          titles.forEach(function(t) {
            if (shownTitles[t]) return;
            shownTitles[t] = true;
            var tc = document.createElement('div');
            tc.className = 'sf-chip' + (titleSelected.indexOf(t) >= 0 ? ' active' : '');
            tc.style.cssText = 'font-size:12px;padding:4px 10px';
            tc.textContent = t;
            (function(i, v){ tc.onclick = function(){ onCondTitleToggle(i, v); }; })(idx, t);
            titleWrap.appendChild(tc);
          });
        });
        box.appendChild(titleWrap);
      }
    } else {
      var inp = document.createElement('input');
      inp.id = 'sf-val-' + idx;
      inp.type = def.type || 'text';
      inp.placeholder = def.placeholder || '';
      inp.value = cond.value || '';
      inp.className = 'fi';
      inp.style.marginTop = '8px';
      (function(i){ inp.oninput = function(){ onCondValueChange(i); }; })(idx);
      box.appendChild(inp);
    }

    wrap.appendChild(box);
  });
}
function clearSearch() {
  searchConds = [];
  searchFilters = { freeword:'', activity:[], morale:[], category:[], gender:[], trainee:[], gsvMin:'', gsvMax:'', aSan:'', nextDate:'', title:'', memo:'' };
  renderSearchConds();
  var disp = document.getElementById('searchDisplayText');
  if (disp) { disp.textContent = '名前・タイトル・稼働・メモ'; disp.style.color = 'var(--text-dim)'; }
  var clr = document.getElementById('searchClearBtn');
  if (clr) clr.style.display = 'none';
  applyAllFilters();
}

function buildFiltersFromConds() {
  var f = { freeword:'', activity:[], morale:[], category:[], gender:[], trainee:[], gsvMin:'', gsvMax:'', aSan:'', nextDate:'', title:'', memo:'' };
  searchConds.forEach(function(cond) {
    if (!cond.value && cond.value !== 0) return;
    var v = cond.value;
    if (cond.field === 'freeword') f.freeword = v;
    else if (cond.field === 'activity') f.activity = v ? v.split(',') : [];
    else if (cond.field === 'morale')   f.morale   = v ? v.split(',') : [];
    else if (cond.field === 'category') f.category = v ? v.split(',') : [];
    else if (cond.field === 'gender')   f.gender   = v ? v.split(',') : [];
    else if (cond.field === 'trainee')  f.trainee  = v ? v.split(',') : [];
    else if (cond.field === 'gsvMin')   f.gsvMin   = v;
    else if (cond.field === 'gsvMax')   f.gsvMax   = v;
    else if (cond.field === 'aSan')     f.aSan     = v;
    else if (cond.field === 'nextDate') f.nextDate = v;
    else if (cond.field === 'title')    f.title    = v;
    // カテゴリ選択時のタイトル絞り込み
    if (cond.field === 'category' && cond.titleValue) { f.title = (f.title ? f.title + ',' : '') + cond.titleValue; }
    else if (cond.field === 'memo')     f.memo     = v;
  });
  return f;
}

function updateSearchDisplay() {
  var labels = searchConds
    .filter(function(c){ return c.value; })
    .map(function(c) {
      var def = SEARCH_FIELDS.filter(function(f){ return f.key===c.field; })[0];
      var label = def ? def.label : c.field;
      if (def && def.type === 'chips') {
        var sel = c.value.split(',');
        var opts = (def.options||[]).filter(function(o){ return sel.indexOf(o.v)>=0; }).map(function(o){ return o.l; });
        return label + ':' + opts.join('/');
      }
      return label + ':' + c.value;
    });

  var disp = document.getElementById('searchDisplayText');
  var clr = document.getElementById('searchClearBtn');
  if (labels.length > 0) {
    if (disp) { disp.textContent = labels.join(' ／ '); disp.style.color = 'var(--accent)'; }
    if (clr) clr.style.display = '';
  } else {
    if (disp) { disp.textContent = '名前・タイトル・稼働・メモ'; disp.style.color = 'var(--text-dim)'; }
    if (clr) clr.style.display = 'none';
  }
}

// 旧関数互換
function toggleSearchField(field, val) { }
function setSearchMode(mode) { }
function onSearchFreeInput() { }
function onGsvRangeChange() { }
function onFieldInputChange() { }

function memberMatchesAllFilters(m) {
  var f = buildFiltersFromConds();
  // フリーワード
  if (f.freeword) {
    var kws = f.freeword.trim().toLowerCase().split(' ').filter(function(k){ return k.length>0; });
    var txt = [(m.lastName||''),(m.firstName||''),(m.title||''),(m.activity||''),(m.memo||''),(m.aSan||''),(m.nextDate||''),(m.instaUrl||'')].join(' ').toLowerCase();
    var hit = false;
    for (var ki=0; ki<kws.length; ki++){ if(txt.indexOf(kws[ki])>=0){ hit=true; break; } }
    if (!hit) return false;
  }
  // 稼働
  if (f.activity.length > 0) {
    var ok = false;
    for (var ai=0; ai<f.activity.length; ai++){ if(f.activity[ai]===(m.activity||'')){ ok=true; break; } }
    if (!ok) return false;
  }
  // やる気
  if (f.morale.length > 0) {
    var mv = parseInt(m.morale) || 1;
    var ok2 = false;
    for (var mi=0; mi<f.morale.length; mi++){ if(parseInt(f.morale[mi])===mv){ ok2=true; break; } }
    if (!ok2) return false;
  }
  // カテゴリ
  if (f.category.length > 0) {
    var cat = detectCategory(m.title||'');
    var ok3 = false;
    for (var ci=0; ci<f.category.length; ci++){ if(f.category[ci]===cat){ ok3=true; break; } }
    if (!ok3) return false;
  }
  // 性別
  if (f.gender.length > 0) {
    var ok4 = false;
    for (var gi=0; gi<f.gender.length; gi++){ if(f.gender[gi]===(m.gender||'male')){ ok4=true; break; } }
    if (!ok4) return false;
  }
  // 研修生
  if (f.trainee.length > 0) { if (!m.trainee) return false; }
  // GSV
  if (f.gsvMin !== '') { if ((m.ptCurrent||0) < parseInt(f.gsvMin)) return false; }
  if (f.gsvMax !== '') { if ((m.ptCurrent||0) > parseInt(f.gsvMax)) return false; }
  // Aさん
  if (f.aSan) { if ((m.aSan||'').toLowerCase().indexOf(f.aSan.toLowerCase()) < 0) return false; }
  // 次回日時
  if (f.nextDate) { if ((m.nextDate||'').toLowerCase().indexOf(f.nextDate.toLowerCase()) < 0) return false; }
  // タイトル
  if (f.title) {
    var titleVals = f.title.split(',');
    var titleMatch = false;
    for (var ti=0; ti<titleVals.length; ti++) {
      if (titleVals[ti] === (m.title||'')) { titleMatch=true; break; }
    }
    if (!titleMatch) return false;
  }
  // メモ
  if (f.memo) { if ((m.memo||'').toLowerCase().indexOf(f.memo.toLowerCase()) < 0) return false; }
  return true;
}

function calcMemberDepth(mOrId, members) {
  // IDでもオブジェクトでも受け取れる
  var cur = (typeof mOrId === 'string')
    ? members.filter(function(x){ return x.id === mOrId; })[0]
    : mOrId;
  var d = 0;
  while (cur && cur.parentId) {
    var par = null;
    for (var pi=0; pi<members.length; pi++) {
      if (members[pi].id === cur.parentId) { par = members[pi]; break; }
    }
    if (!par) break;
    d++;
    cur = par;
  }
  return d;
}

function applyAllFilters() {
  var hasFilter = searchConds.length > 0 && searchConds.some(function(c){ return !!c.value; });

  var countEl = document.getElementById('searchResultCount');

  if (!hasFilter) {
    if (countEl) countEl.textContent = '';
    // フィルターなし → 通常ツリー再描画
    renderCurrentView();
    return;
  }

  // フィルターあり → マッチしたメンバーをフラットリストで表示
  var mapType = currentView === 'ideal' ? 'ideal' : 'current';
  var allMembers = membersForMap(mapType);
  var matched = allMembers.filter(function(m) { return memberMatchesAllFilters(m); });

  // 件数表示
  if (countEl) countEl.textContent = matched.length + '人';

  var containerId = mapType === 'current' ? 'treeCurrent' : 'treeIdeal';
  var container = document.getElementById(containerId);
  if (!container) return;

  if (matched.length === 0) {
    container.innerHTML = '<div class="empty" style="padding:32px;text-align:center;color:var(--text-dim)">該当なし</div>';
    return;
  }

  // フラットカードとして表示（ツリー構造なし、深さ情報は保持）
  container.innerHTML = matched.map(function(m) {
    var depth = calcMemberDepth(m, allMembers);
    var depthColor = getFamilyColor(m.id, allMembers, depth);
    var actLabel = m.activity ? (m.actRate ? m.activity + m.actRate + '%' : (m.activity === 'S' ? 'S 120%' : m.activity)) : ''; // v492: Sも実測優先
    var actColor = m.activity === 'S' ? 'var(--s)' : m.activity === 'A' ? 'var(--a)' : m.activity === 'B' ? 'var(--b)' : m.activity === 'C' ? 'var(--c)' : 'var(--text-dim)';
    var ptDisplay = m.ptCurrent > 0 ? m.ptCurrent.toLocaleString() : '-';
    var g = m.gender || 'male';
    var avStyle = titleAvatarStyle(m.title);
    var parentMember = m.parentId ? allMembers.filter(function(x){ return x.id===m.parentId; })[0] : null;
    var parentChip = parentMember ? '<div class="parent-chip"><span class="parent-chip-arrow">↳</span>' + (parentMember.lastName||'') + ' ' + (parentMember.firstName||'') + '</div>' : '';
    var instaBtn = m.instaUrl ? '<a class="insta-btn" href="' + m.instaUrl + '" target="_blank" onclick="event.stopPropagation()" title="Instagram"><svg viewBox="0 0 24 24"><path fill="white" d="M12 2.163c3.204 0 3.584.012 4.85.07 3.252.148 4.771 1.691 4.919 4.919.058 1.265.069 1.645.069 4.849 0 3.205-.012 3.584-.069 4.849-.149 3.225-1.664 4.771-4.919 4.919-1.266.058-1.644.07-4.85.07-3.204 0-3.584-.012-4.849-.07-3.26-.149-4.771-1.699-4.919-4.92-.058-1.265-.07-1.644-.07-4.849 0-3.204.013-3.583.07-4.849.149-3.227 1.664-4.771 4.919-4.919 1.266-.057 1.645-.069 4.849-.069zm0-2.163c-3.259 0-3.667.014-4.947.072-4.358.2-6.78 2.618-6.98 6.98-.059 1.281-.073 1.689-.073 4.948 0 3.259.014 3.668.072 4.948.2 4.358 2.618 6.78 6.98 6.98 1.281.058 1.689.072 4.948.072 3.259 0 3.668-.014 4.948-.072 4.354-.2 6.782-2.618 6.979-6.98.059-1.28.073-1.689.073-4.948 0-3.259-.014-3.667-.072-4.947-.196-4.354-2.617-6.78-6.979-6.98-1.281-.059-1.69-.073-4.949-.073zm0 5.838c-3.403 0-6.162 2.759-6.162 6.162s2.759 6.163 6.162 6.163 6.162-2.759 6.162-6.163c0-3.403-2.759-6.162-6.162-6.162zm0 10.162c-2.209 0-4-1.79-4-4 0-2.209 1.791-4 4-4s4 1.791 4 4c0 2.21-1.791 4-4 4zm6.406-11.845c-.796 0-1.441.645-1.441 1.44s.645 1.44 1.441 1.44c.795 0 1.439-.645 1.439-1.44s-.644-1.44-1.439-1.44z"/></svg></a>' : '';

    return '<div class="nw" id="nw-' + m.id + '" style="margin-bottom:4px">'
      + '<div class="nc' + (m.trainee ? ' trainee' : '') + (m.traineeResult==='流れた' ? ' result-ng' : m.traineeResult==='ユーザー' ? ' result-user' : '') + '" id="nc-' + m.id + '" style="border-left:3px solid ' + depthColor + '">'
      + instaBtn
      + '<div class="card-main" onclick="selectCard(\'' + m.id + '\',event)" ondblclick="if(state.isEditor){openEdit(\'' + m.id + '\');event.stopPropagation()}">'
      + '<div class="depth-num" style="background:' + depthColor + '1a;color:' + depthColor + ';border:1px solid ' + depthColor + '40">' + depth + '</div>'
      + '<div class="av ' + g + ' av-title" style="' + avStyle + '">' + (m.title||'–') + '</div>'
      + '<div style="flex:1;min-width:0;overflow:hidden">'
      + (parentChip ? '<div style="display:flex;align-items:center;justify-content:space-between;gap:4px">' + parentChip + (actLabel ? '<span class="info-act" style="color:' + actColor + ';font-size:10px;margin-left:auto">' + actLabel + '</span>' : '') + '</div>' : '')
      + '<div class="nm ' + g + '">' + (m.lastName||'') + ' ' + (m.firstName||'') + '</div>'
      + '</div>'
      + '<div style="display:flex;flex-direction:column;align-items:flex-end;gap:2px;flex-shrink:0">'
      + '<div class="morale-emoji">' + moraleIcon(m.morale||1) + '</div>'
      + '<span class="info-pt">' + ptDisplay + (m.ptFixed>0 ? '<span class="info-pt-fix"> (' + m.ptFixed.toLocaleString() + ')</span>' : '') + '</span>'
      + '</div>'
      + '</div>'
      + (m.memo ? '<div class="memo show">' + evEsc(m.memo) + '</div>' : '')
      + '</div></div>';
  }).join('');
}

// 旧関数の互換性維持
function onSearchInput() { onSearchFreeInput(); }
