    var perm = (d && d.perm) || (_own ? _own.perm : 'view');
    if (perm !== 'edit') { _hideSwitching(); toast('👁 閲覧のみで共有されています（編集するには相手に「編集」で共有してもらってください）'); return; }
    _pendingSharedEditId = r.srcId;
